{"command": "python3 -c "
import json

with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

for path, methods in spec.get('paths', {}).items():
    for method, op in methods.items():
        print(f'{method.upper():4} {path:40} opId={op.get(\"operationId\")} tags={op.get(\"tags\", [])}')
"", "summary": "List all operationIds and methods"}

