	if err != nil {
		return nil, errors.New("user not found")
	}

	u.AssignedLocationId = assignedLoc
	u.Latitude = lat
	u.Longitude = lng
	u.LocationRecordedAt = recAt
	if len(certsJSON) > 0 {
		_ = json.Unmarshal(certsJSON, &u.Certifications)
	}
	if u.Certifications == nil {
		u.Certifications = []model.Certification{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}

	return &u, nil
}

func CreateUser(ctx context.Context, actorID, actorRole string, req struct {
	Username           string                `json:"username"`
	InitialPassword    string                `json:"initialPassword"`
	Email              *string               `json:"email"`
	FullName           *string               `json:"fullName"`
	Phone              *string               `json:"phone"`
	Roles              []string              `json:"roles"`
