	})

	_ = RecomputeServiceabilitySnapshot(ctx)

	return GetLocationByID(ctx, loc.LocationId)
}

func UpdateLocation(ctx context.Context, actorID, actorRole string, loc model.Location) (*model.Location, error) {
	isCP := loc.Functions.CollectionPoint != nil && *loc.Functions.CollectionPoint
	isTP := loc.Functions.TransferPoint != nil && *loc.Functions.TransferPoint
	isHub := loc.Functions.Hub != nil && *loc.Functions.Hub
	isLab := loc.Functions.Laboratory != nil && *loc.Functions.Laboratory

