FROM locations
WHERE id = $1;
`, locationID).Scan(&loc.LocationId, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &isCP, &isTP, &isHub, &isLab)
