package service

import (
	"container/heap"
	"context"
	"encoding/json"
	"math"
	"time"

	"backend/internal/db"
	"backend/internal/model"
)

func HaversineDistance(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0 // Earth radius in km
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLon := (lon2 - lon1) * math.Pi / 180.0
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func RecomputeServiceabilitySnapshot(ctx context.Context) error {
	rows, err := db.Pool.Query(ctx, `
SELECT id, name, latitude, longitude, coverage_km
FROM locations
WHERE active = true AND is_collection_point = true;
`)
	if err != nil {
		return err
	}
	defer rows.Close()

	regions := make([]model.ServiceabilityRegion, 0)
	for rows.Next() {
		var r model.ServiceabilityRegion
		if err := rows.Scan(&r.LocationId, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return err
		}
		regions = append(regions, r)
	}

	regionsJSON, _ := json.Marshal(regions)

	var nextVersion int
	err = db.Pool.QueryRow(ctx, "SELECT COALESCE(MAX(version), 0) + 1 FROM serviceability_snapshots").Scan(&nextVersion)
	if err != nil {
		nextVersion = 1
	}

	_, err = db.Pool.Exec(ctx, `
INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
VALUES ($1, 'complete', NOW(), $1, $2, $3);
`, nextVersion, regionsJSON, len(regions))

	return err
}

func GetLatestServiceabilitySnapshot(ctx context.Context) (*model.ServiceabilitySnapshot, error) {
	var snap model.ServiceabilitySnapshot
	var regionsJSON []byte
	var compAt time.Time

	err := db.Pool.QueryRow(ctx, `
SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
FROM serviceability_snapshots
WHERE status = 'complete'
ORDER BY version DESC
LIMIT 1;
`).Scan(&snap.Version, &snap.Status, &compAt, &snap.NetworkRevision, &regionsJSON, &snap.ActiveCollectionPointCount)
	if err != nil {
		// If none exists, compute one
		_ = RecomputeServiceabilitySnapshot(ctx)
		return GetLatestServiceabilitySnapshot(ctx)
	}

	snap.ComputedAt = compAt.UTC().Format(time.RFC3339)
	_ = json.Unmarshal(regionsJSON, &snap.Regions)
	if snap.Regions == nil {
		snap.Regions = []model.ServiceabilityRegion{}
	}

	return &snap, nil
}

type CheckServiceabilityInput struct {
	Origin               model.Coordinate `json:"origin"`
	OriginType           *string          `json:"originType"`
	OriginNodeId         *string          `json:"originNodeId"`
	SampleTypeId         string           `json:"sampleTypeId"`
	RequestedAt          string           `json:"requestedAt"`
	DeliveryDeadline     string           `json:"deliveryDeadline"`
	EarliestCollectionAt *string          `json:"earliestCollectionAt"`
	LatestCollectionAt   *string          `json:"latestCollectionAt"`
}

type CheckServiceabilityResult struct {
	Serviceable           bool    `json:"serviceable"`
	Reason                string  `json:"reason"`
	TargetLaboratoryId    *string `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt    *string `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion int     `json:"serviceabilityVersion"`
	NearestCollectionNode *string `json:"-"`
	RoutePath             []string `json:"-"`
	RouteCost             float64  `json:"-"`
	TotalTravelMinutes    int      `json:"-"`
}

type RouteNode struct {
	LocationID    string
	TotalMinutes  int
	TotalCost     float64
	Path          []string
	index         int
}

type PriorityQueue []*RouteNode

func (pq PriorityQueue) Len() int           { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].TotalMinutes < pq[j].TotalMinutes }
func (pq PriorityQueue) Swap(i, j int)      { pq[i], pq[j] = pq[j], pq[i]; pq[i].index = i; pq[j].index = j }
func (pq *PriorityQueue) Push(x any) {
	n := len(*pq)
	item := x.(*RouteNode)
	item.index = n
	*pq = append(*pq, item)
}
func (pq *PriorityQueue) Pop() any {
	old := *pq
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	item.index = -1
	*pq = old[0 : n-1]
	return item
}

type DBLocationInfo struct {
	ID                  string
	Active              bool
	HandlingMinutes     int
	IsLab               bool
	CapacityUnits       int
	ReservedUnits       int
	CooledCapacityUnits int
	CooledReservedUnits int
}

type DBConnectionInfo struct {
	ID                  string
	FromID              string
	ToID                string
	TravelMinutes       int
	CostUnits           float64
	Cooled              bool
	Active              bool
	CapacityUnits       int
	ReservedUnits       int
	CooledCapacityUnits int
	CooledReservedUnits int
}

func CheckServiceability(ctx context.Context, in CheckServiceabilityInput) (*CheckServiceabilityResult, error) {
	snap, err := GetLatestServiceabilitySnapshot(ctx)
	if err != nil {
		return nil, err
	}

	requestedTime, err := time.Parse(time.RFC3339, in.RequestedAt)
	if err != nil {
		requestedTime = time.Now().UTC()
	}
	deadlineTime, err := time.Parse(time.RFC3339, in.DeliveryDeadline)
	if err != nil {
		deadlineTime = requestedTime.Add(4 * time.Hour)
	}

	// 1. Get sample type
	st, err := GetSampleTypeByID(ctx, in.SampleTypeId)
	if err != nil {
		return &CheckServiceabilityResult{
			Serviceable:           false,
			Reason:                "handling_rules_unsatisfiable",
			ServiceabilityVersion: snap.Version,
		}, nil
	}

	// 2. Coverage check
	var nearestNodeID string
	minDist := math.MaxFloat64

	if in.OriginNodeId != nil && *in.OriginNodeId != "" {
		nearestNodeID = *in.OriginNodeId
		var active bool
		_ = db.Pool.QueryRow(ctx, "SELECT active FROM locations WHERE id = $1", nearestNodeID).Scan(&active)
		if !active {
			return &CheckServiceabilityResult{
				Serviceable:           false,
				Reason:                "outside_service_coverage",
				ServiceabilityVersion: snap.Version,
			}, nil
		}
	} else {
		for _, r := range snap.Regions {
			d := HaversineDistance(in.Origin.Latitude, in.Origin.Longitude, r.Latitude, r.Longitude)
			cov := r.CoverageKm
			if cov <= 0 || cov > 5.0 {
				cov = 5.0
			}
			if d <= cov && d < minDist {
				minDist = d
				nearestNodeID = r.LocationId
			}
		}

		if nearestNodeID == "" {
			return &CheckServiceabilityResult{
				Serviceable:           false,
				Reason:                "outside_service_coverage",
				ServiceabilityVersion: snap.Version,
			}, nil
		}
	}

	// 3. Find accepting laboratories
	labRows, err := db.Pool.Query(ctx, `
SELECT l.id, l.handling_minutes, l.capacity_units, l.reserved_units, l.cooled_capacity_units, l.cooled_reserved_units
FROM locations l
JOIN laboratory_acceptance la ON l.id = la.laboratory_id
WHERE l.active = true AND l.is_laboratory = true AND la.sample_type_id = $1 AND la.accepts = true;
`, in.SampleTypeId)
	if err != nil {
		return nil, err
	}
	defer labRows.Close()

	type LabCandidate struct {
		ID                  string
		HandlingMinutes     int
		CapacityUnits       int
		ReservedUnits       int
		CooledCapacityUnits int
		CooledReservedUnits int
	}
	labs := make([]LabCandidate, 0)
	for labRows.Next() {
		var lc LabCandidate
		if err := labRows.Scan(&lc.ID, &lc.HandlingMinutes, &lc.CapacityUnits, &lc.ReservedUnits, &lc.CooledCapacityUnits, &lc.CooledReservedUnits); err != nil {
			return nil, err
		}
		labs = append(labs, lc)
	}

	if len(labs) == 0 {
		return &CheckServiceabilityResult{
			Serviceable:           false,
			Reason:                "no_accepting_laboratory",
			ServiceabilityVersion: snap.Version,
		}, nil
	}

	// 4. Load all active locations and connections for graph search
	locRows, err := db.Pool.Query(ctx, `
SELECT id, active, handling_minutes, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM locations
WHERE active = true;
`)
	if err != nil {
		return nil, err
	}
	defer locRows.Close()

	locMap := make(map[string]DBLocationInfo)
	for locRows.Next() {
		var l DBLocationInfo
		if err := locRows.Scan(&l.ID, &l.Active, &l.HandlingMinutes, &l.IsLab, &l.CapacityUnits, &l.ReservedUnits, &l.CooledCapacityUnits, &l.CooledReservedUnits); err != nil {
			return nil, err
		}
		locMap[l.ID] = l
	}

	connRows, err := db.Pool.Query(ctx, `
SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM connections
WHERE active = true;
`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	adj := make(map[string][]DBConnectionInfo)
	for connRows.Next() {
		var c DBConnectionInfo
		if err := connRows.Scan(&c.ID, &c.FromID, &c.ToID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits); err != nil {
			return nil, err
		}
		adj[c.FromID] = append(adj[c.FromID], c)
	}

	// 5. Dijkstra shortest path search to finding best laboratory
	var bestResult *CheckServiceabilityResult
	foundAnyRouteWithoutCapacity := false
	foundAnyRoute := false

	originDwell := 15 // minutes for collection pickup

	for _, lab := range labs {
		// If origin node is already the laboratory
		if nearestNodeID == lab.ID {
			foundAnyRoute = true
			totalMins := originDwell + lab.HandlingMinutes
			arrival := requestedTime.Add(time.Duration(totalMins) * time.Minute)

			hasCap := true
			if st.RequiresCooledRoute {
				if lab.CooledCapacityUnits-lab.CooledReservedUnits <= 0 {
					hasCap = false
				}
			} else {
				if lab.CapacityUnits-lab.ReservedUnits <= 0 {
					hasCap = false
				}
			}

			if !hasCap {
				foundAnyRouteWithoutCapacity = true
				continue
			}

			if arrival.After(deadlineTime) {
				continue
			}

			arrStr := arrival.UTC().Format(time.RFC3339)
			bestResult = &CheckServiceabilityResult{
				Serviceable:           true,
				Reason:                "serviceable",
				TargetLaboratoryId:    &lab.ID,
				EstimatedArrivalAt:    &arrStr,
				ServiceabilityVersion: snap.Version,
				NearestCollectionNode: &nearestNodeID,
				RoutePath:             []string{nearestNodeID},
				RouteCost:             0.0,
				TotalTravelMinutes:    totalMins,
			}
			break
		}

		// Run Dijkstra
		dist := make(map[string]int)
		cost := make(map[string]float64)
		prev := make(map[string]string)
		capacityOk := make(map[string]bool)

		pq := &PriorityQueue{}
		heap.Init(pq)

		startLoc := locMap[nearestNodeID]
		initialMins := originDwell + startLoc.HandlingMinutes
		dist[nearestNodeID] = initialMins
		cost[nearestNodeID] = 0.0
		capacityOk[nearestNodeID] = true

		if st.RequiresCooledRoute && (startLoc.CooledCapacityUnits-startLoc.CooledReservedUnits <= 0) {
			capacityOk[nearestNodeID] = false
		}
		if !st.RequiresCooledRoute && (startLoc.CapacityUnits-startLoc.ReservedUnits <= 0) {
			capacityOk[nearestNodeID] = false
		}

		heap.Push(pq, &RouteNode{
			LocationID:   nearestNodeID,
			TotalMinutes: initialMins,
			TotalCost:    0.0,
			Path:         []string{nearestNodeID},
		})

		for pq.Len() > 0 {
			curr := heap.Pop(pq).(*RouteNode)
			if curr.LocationID == lab.ID {
				break
			}
			if curr.TotalMinutes > dist[curr.LocationID] {
				continue
			}

			for _, edge := range adj[curr.LocationID] {
				nextLoc, ok := locMap[edge.ToID]
				if !ok || !nextLoc.Active {
					continue
				}

				// Check cooled requirement
				if st.RequiresCooledRoute && !edge.Cooled {
					continue
				}

				edgeCapOk := true
				if st.RequiresCooledRoute {
					if (edge.CooledCapacityUnits-edge.CooledReservedUnits <= 0) || (nextLoc.CooledCapacityUnits-nextLoc.CooledReservedUnits <= 0) {
						edgeCapOk = false
					}
				} else {
					if (edge.CapacityUnits-edge.ReservedUnits <= 0) || (nextLoc.CapacityUnits-nextLoc.ReservedUnits <= 0) {
						edgeCapOk = false
					}
				}

				newMins := curr.TotalMinutes + edge.TravelMinutes + nextLoc.HandlingMinutes
				newCost := curr.TotalCost + edge.CostUnits

				if oldMins, seen := dist[edge.ToID]; !seen || newMins < oldMins {
					dist[edge.ToID] = newMins
					cost[edge.ToID] = newCost
					prev[edge.ToID] = curr.LocationID
					capacityOk[edge.ToID] = capacityOk[curr.LocationID] && edgeCapOk

					newPath := make([]string, len(curr.Path)+1)
					copy(newPath, curr.Path)
					newPath[len(curr.Path)] = edge.ToID

					heap.Push(pq, &RouteNode{
						LocationID:   edge.ToID,
						TotalMinutes: newMins,
						TotalCost:    newCost,
						Path:         newPath,
					})
				}
			}
		}

		if _, reached := dist[lab.ID]; reached {
			foundAnyRoute = true
			if !capacityOk[lab.ID] {
				foundAnyRouteWithoutCapacity = true
				continue
			}

			totalMins := dist[lab.ID]
			arrival := requestedTime.Add(time.Duration(totalMins) * time.Minute)
			if arrival.After(deadlineTime) {
				continue
			}

			// Reconstruct path
			curr := lab.ID
			path := []string{curr}
			for curr != nearestNodeID {
				p := prev[curr]
				if p == "" {
					break
				}
				path = append([]string{p}, path...)
				curr = p
			}

			arrStr := arrival.UTC().Format(time.RFC3339)
			labID := lab.ID
			res := &CheckServiceabilityResult{
				Serviceable:           true,
				Reason:                "serviceable",
				TargetLaboratoryId:    &labID,
				EstimatedArrivalAt:    &arrStr,
				ServiceabilityVersion: snap.Version,
				NearestCollectionNode: &nearestNodeID,
				RoutePath:             path,
				RouteCost:             cost[lab.ID],
				TotalTravelMinutes:    totalMins,
			}

			if bestResult == nil || res.TotalTravelMinutes < bestResult.TotalTravelMinutes {
				bestResult = res
			}
		}
	}

	if bestResult != nil {
		return bestResult, nil
	}

	if !foundAnyRoute {
		return &CheckServiceabilityResult{
			Serviceable:           false,
			Reason:                "no_route",
			ServiceabilityVersion: snap.Version,
		}, nil
	}

	if foundAnyRouteWithoutCapacity {
		return &CheckServiceabilityResult{
			Serviceable:           false,
			Reason:                "insufficient_capacity",
			ServiceabilityVersion: snap.Version,
		}, nil
	}

	return &CheckServiceabilityResult{
		Serviceable:           false,
		Reason:                "deadline_unreachable",
		ServiceabilityVersion: snap.Version,
	}, nil
}

