package service

import (
	"context"
	"errors"
	"time"

	"backend/internal/db"
	"backend/internal/model"

	"github.com/google/uuid"
)

type EligibleWorker struct {
	UserID        string
	ActiveCount   int
	DeclineCount  int
	TotalCount    int
	CapacityUnits int
}

func FindAndOfferWorker(ctx context.Context, assignmentID string) error {
	var kind, sampleID string
	var nodeID, labID *string
	var declinedIDs []string

	err := db.Pool.QueryRow(ctx, `
SELECT kind, sample_id, node_id, laboratory_id, declined_worker_ids
FROM assignments
WHERE id = $1;
`, assignmentID).Scan(&kind, &sampleID, &nodeID, &labID, &declinedIDs)
	if err != nil {
		return err
	}

	var sampleTypeID string
	err = db.Pool.QueryRow(ctx, "SELECT sample_type_id FROM samples WHERE id = $1", sampleID).Scan(&sampleTypeID)
	if err != nil {
		return err
	}

	st, err := GetSampleTypeByID(ctx, sampleTypeID)
	if err != nil {
		return err
	}

	targetRole := ""
	switch kind {
	case "collection":
		targetRole = "collection_professional"
	case "transport":
		targetRole = "delivery_partner"
	case "node":
		targetRole = "node_handler"
	case "laboratory":
		targetRole = "laboratory_team"
	}

	// Query available active workers with target role
	rows, err := db.Pool.Query(ctx, `
SELECT u.id, u.qualifications, u.certifications, u.assigned_location_id, u.capacity_units,
       COALESCE(wp.decline_count, 0) as decline_count,
       (SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status IN ('accepted', 'in_transit', 'arrived')) as active_count,
       (SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id) as total_count
FROM users u
LEFT JOIN worker_penalties wp ON u.id = wp.worker_id
WHERE u.active = true AND u.available = true AND $1 = ANY(u.roles);
`, targetRole)
	if err != nil {
		return err
	}
	defer rows.Close()

	candidates := make([]EligibleWorker, 0)
	declinedMap := make(map[string]bool)
	for _, d := range declinedIDs {
		declinedMap[d] = true
	}

	for rows.Next() {
		var uid string
		var quals []string
		var certsJSON []byte
		var assignedLoc *string
		var capUnits, decCount, actCount, totCount int

		if err := rows.Scan(&uid, &quals, &certsJSON, &assignedLoc, &capUnits, &decCount, &actCount, &totCount); err != nil {
			return err
		}

		if declinedMap[uid] {
			continue
		}

		// Check location assignment
		if kind == "node" && nodeID != nil && *nodeID != "" {
			if assignedLoc != nil && *assignedLoc != "" && *assignedLoc != *nodeID {
				continue
			}
		}
		if kind == "laboratory" && labID != nil && *labID != "" {
			if assignedLoc != nil && *assignedLoc != "" && *assignedLoc != *labID {
				continue
			}
		}

		// Check qualifications for collection
		if kind == "collection" && st.QualifiedCollectorRequired {
			qualified := false
			for _, q := range quals {
				if q == st.RequiredQualification || q == st.Name || q == "amber_certified" || q == "indigo_certified" || q == "frost_certified" || q == "pulse_certified" {
					if q == st.RequiredQualification || q == st.Name {
						qualified = true
						break
					}
				}
			}
			if !qualified {
				// Check certifications
				var certs []model.Certification
				// ignore err
				for _, c := range certs {
					if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
						qualified = true
						break
					}
				}
			}
			if !qualified {
				continue
			}
		}

		candidates = append(candidates, EligibleWorker{
			UserID:        uid,
			ActiveCount:   actCount,
			DeclineCount:  decCount,
			TotalCount:    totCount,
			CapacityUnits: capUnits,
		})
	}

	if len(candidates) == 0 {
		// No qualified worker available
		if kind == "collection" && st.QualifiedCollectorRequired {
			_ = db.Pool.QueryRow(ctx, `
UPDATE samples
SET status = 'exception',
    exception_details = jsonb_build_object('reason', 'no_qualified_worker_available', 'assignmentId', $1)
WHERE id = $2;
`, assignmentID, sampleID)
			_ = RecordAudit(ctx, "system", "system", "system", "sample.exception", "sample", sampleID, false, map[string]any{
				"reason":       "no_qualified_worker_available",
				"assignmentId": assignmentID,
			})
		}
		return nil
	}

	// Sort candidates by: active_count asc, decline_count asc, total_count asc
	best := candidates[0]
	for _, c := range candidates[1:] {
		if c.ActiveCount < best.ActiveCount ||
