package service

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"backend/internal/db"
	"backend/internal/model"

	"github.com/google/uuid"
)

func CollectAndSealSample(ctx context.Context, actorID, actorRole, sampleID, assignmentID string, collectedAt string, containerType string, observedTemp float64) (string, string, string, string, bool, error) {
	var stID string
	err := db.Pool.QueryRow(ctx, "SELECT sample_type_id FROM samples WHERE id = $1", sampleID).Scan(&stID)
	if err != nil {
		return "", "", "", "", false, errors.New("sample not found")
	}

	st, err := GetSampleTypeByID(ctx, stID)
	if err != nil {
		return "", "", "", "", false, err
	}

	handlingCompliant := true
	if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
		handlingCompliant = false
	}
	if containerType != "" && st.ContainerType != "" && containerType != st.ContainerType {
		handlingCompliant = false
	}

	cTime, err := time.Parse(time.RFC3339, collectedAt)
	if err != nil {
		cTime = time.Now().UTC()
	}

	sampleStatus := "sealed"
	if !handlingCompliant {
		sampleStatus = "exception"
		_, _ = db.Pool.Exec(ctx, `
UPDATE samples
SET status = $1, sealed = true, sealed_at = $2, current_holder_id = $3,
    exception_details = jsonb_build_object('reason', 'handling_non_compliant', 'temperature', $4, 'container', $5)
WHERE id = $6;
`, sampleStatus, cTime, actorID, observedTemp, containerType, sampleID)
	} else {
		_, _ = db.Pool.Exec(ctx, `
UPDATE samples
SET status = $1, sealed = true, sealed_at = $2, current_holder_id = $3
WHERE id = $4;
`, sampleStatus, cTime, actorID, sampleID)
	}

	// Update assignment
	_, _ = db.Pool.Exec(ctx, "UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE id = $1", assignmentID)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "sample.collect_and_seal", "sample", sampleID, handlingCompliant, map[string]any{
		"assignmentId":      assignmentID,
		"containerType":     containerType,
		"observedTemp":      observedTemp,
		"handlingCompliant": handlingCompliant,
	})

	return sampleID, sampleStatus, actorID, cTime.UTC().Format(time.RFC3339), handlingCompliant, nil
}

func InitiateHandoff(ctx context.Context, actorID, actorRole, sampleID string, fromAssignmentID, toAssignmentID *string, receiverID, initiatedAt string) (string, string, string, string, string, error) {
	var currentHolderID *string
	err := db.Pool.QueryRow(ctx, "SELECT current_holder_id FROM samples WHERE id = $1", sampleID).Scan(&currentHolderID)
	if err != nil {
		return "", "", "", "", "", errors.New("sample not found")
	}

	senderID := actorID
	handoffID := uuid.New().String()

	_, err = db.Pool.Exec(ctx, `
INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, current_holder_id, status, sender_confirmed, receiver_confirmed, sender_confirmed_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', true, false, NOW());
`, handoffID, sampleID, fromAssignmentID, toAssignmentID, senderID, receiverID, senderID)
	if err != nil {
		return "", "", "", "", "", err
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "handoff.initiate", "handoff", handoffID, true, map[string]any{
		"sampleId":   sampleID,
		"senderId":   senderID,
		"receiverId": receiverID,
	})

	return handoffID, senderID, receiverID, senderID, "pending", nil
}

func ConfirmHandoff(ctx context.Context, actorID, actorRole, handoffID, confirmationSide string, confirmedAt string) (string, string, bool, bool, string, error) {
	var sampleID, senderID, receiverID, currentHolderID, status string
	var senderConfirmed, receiverConfirmed bool

	err := db.Pool.QueryRow(ctx, `
SELECT sample_id, sender_id, receiver_id, current_holder_id, status, sender_confirmed, receiver_confirmed
FROM handoffs
WHERE id = $1;
`, handoffID).Scan(&sampleID, &senderID, &receiverID, &currentHolderID, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		return "", "", false, false, "", errors.New("handoff not found")
	}

	cTime, err := time.Parse(time.RFC3339, confirmedAt)
	if err != nil {
		cTime = time.Now().UTC()
	}

	if confirmationSide == "sender" {
		senderConfirmed = true
		_, _ = db.Pool.Exec(ctx, "UPDATE handoffs SET sender_confirmed = true, sender_confirmed_at = $1 WHERE id = $2", cTime, handoffID)
	} else if confirmationSide == "receiver" {
		receiverConfirmed = true
		_, _ = db.Pool.Exec(ctx, "UPDATE handoffs SET receiver_confirmed = true, receiver_confirmed_at = $1 WHERE id = $2", cTime, handoffID)
	}

	if senderConfirmed && receiverConfirmed && status != "confirmed" {
		status = "confirmed"
		currentHolderID = receiverID

		_, _ = db.Pool.Exec(ctx, "UPDATE handoffs SET status = 'confirmed', current_holder_id = $1 WHERE id = $2", receiverID, handoffID)
		_, _ = db.Pool.Exec(ctx, "UPDATE samples SET current_holder_id = $1, status = 'in_transit' WHERE id = $2", receiverID, sampleID)

		_ = RecordAudit(ctx, actorID, actorRole, actorRole, "handoff.transfer_custody", "sample", sampleID, true, map[string]any{
			"handoffId":       handoffID,
			"previousHolder": senderID,
			"newHolder":      receiverID,
		})
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "handoff.confirm", "handoff", handoffID, true, map[string]any{
		"confirmationSide": confirmationSide,
		"status":           status,
	})

	return handoffID, status, senderConfirmed, receiverConfirmed, currentHolderID, nil
}

func RecordHandlingCheckpoint(ctx context.Context, actorID, actorRole, sampleID string, assignmentID, locationID *string, containerType string, observedTemp float64, recordedAt string) (string, string, bool, string, error) {
	var stID, currentStatus string
	err := db.Pool.QueryRow(ctx, "SELECT sample_type_id, status FROM samples WHERE id = $1", sampleID).Scan(&stID, &currentStatus)
	if err != nil {
		return "", "", false, "", errors.New("sample not found")
	}

	st, err := GetSampleTypeByID(ctx, stID)
	if err != nil {
		return "", "", false, "", err
	}

	compliant := true
	if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
		compliant = false
	}
	if containerType != "" && st.ContainerType != "" && containerType != st.ContainerType {
		compliant = false
	}

	sampleStatus := currentStatus
	if !compliant {
		sampleStatus = "exception"
		_, _ = db.Pool.Exec(ctx, `
UPDATE samples
SET status = 'exception',
    exception_details = jsonb_build_object('reason', 'checkpoint_non_compliant', 'temperature', $1, 'container', $2)
WHERE id = $3;
`, observedTemp, containerType, sampleID)
	}

	checkpointID := uuid.New().String()
	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "sample.handling_checkpoint", "sample", sampleID, compliant, map[string]any{
		"checkpointId":  checkpointID,
		"assignmentId":  assignmentID,
		"locationId":    locationID,
		"containerType": containerType,
		"observedTemp":  observedTemp,
		"compliant":     compliant,
		"sampleStatus":  sampleStatus,
	})

	return checkpointID, sampleID, compliant, sampleStatus, nil
}

func ConfirmLaboratoryReceipt(ctx context.Context, actorID, actorRole, sampleID, laboratoryID, receivedAt string) (string, string, string, string, error) {
	rTime, err := time.Parse(time.RFC3339, receivedAt)
	if err != nil {
		rTime = time.Now().UTC()
	}

	var journeyID *string
	_ = db.Pool.QueryRow(ctx, "SELECT active_journey_id FROM samples WHERE id = $1", sampleID).Scan(&journeyID)

	_, err = db.Pool.Exec(ctx, `
UPDATE samples
SET status = 'received', received_laboratory_id = $1
WHERE id = $2;
`, laboratoryID, sampleID)
	if err != nil {
		return "", "", "", "", err
	}

	// If journey exists, complete and release capacity
	if journeyID != nil && *journeyID != "" {
		_, _ = db.Pool.Exec(ctx, "UPDATE journeys SET status = 'completed', updated_at = NOW() WHERE id = $1", *journeyID)
		ReleaseCapacityReservations(ctx, *journeyID)
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "laboratory.receipt", "sample", sampleID, true, map[string]any{
		"laboratoryId": laboratoryID,
		"receivedAt":   rTime.Format(time.RFC3339),
	})

	return sampleID, laboratoryID, "received", rTime.UTC().Format(time.RFC3339), nil
}

func RecordLaboratoryException(ctx context.Context, actorID, actorRole, sampleID, laboratoryID, reason, observedAt string) (string, string, string, string, error) {
	oTime, err := time.Parse(time.RFC3339, observedAt)
	if err != nil {
		oTime = time.Now().UTC()
	}

	var journeyID *string
	_ = db.Pool.QueryRow(ctx, "SELECT active_journey_id FROM samples WHERE id = $1", sampleID).Scan(&journeyID)

	_, err = db.Pool.Exec(ctx, `
UPDATE samples
SET status = 'exception',
    exception_details = jsonb_build_object('reason', $1, 'laboratoryId', $2, 'observedAt', $3)
WHERE id = $4;
`, reason, laboratoryID, oTime.Format(time.RFC3339), sampleID)
	if err != nil {
		return "", "", "", "", err
	}

	if journeyID != nil && *journeyID != "" {
		ReleaseCapacityReservations(ctx, *journeyID)
	}

	exceptionID := uuid.New().String()
	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "laboratory.exception", "sample", sampleID, false, map[string]any{
		"exceptionId":  exceptionID,
		"laboratoryId": laboratoryID,
		"reason":       reason,
	})

	return exceptionID, sampleID, "exception", reason, nil
}

func RecordWorkerLocation(ctx context.Context, actorID, actorRole, assignmentID string, coord model.Coordinate, seq int, recordedAt string) (string, model.Coordinate, int, string, error) {
	rTime, err := time.Parse(time.RFC3339, recordedAt)
	if err != nil {
		rTime = time.Now().UTC()
	}

	// Update worker location in users table
	_, _ = db.Pool.Exec(ctx, `
UPDATE users
SET latitude = $1, longitude = $2, location_recorded_at = $3
WHERE id = $4;
`, coord.Latitude, coord.Longitude, rTime, actorID)

	// Insert into log
	logID := uuid.New().String()
	_, _ = db.Pool.Exec(ctx, `
INSERT INTO worker_location_logs (id, assignment_id, worker_id, latitude, longitude, sequence, recorded_at)
VALUES ($1, $2, $3, $4, $5, $6, $7);
`, logID, assignmentID, actorID, coord.Latitude, coord.Longitude, seq, rTime)

	// If worker currently holds custody of sample, update sample's location
	_, _ = db.Pool.Exec(ctx, `
UPDATE samples
SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
WHERE current_holder_id = $4;
`, coord.Latitude, coord.Longitude, rTime, actorID)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "worker.record_location", "assignment", assignmentID, true, map[string]any{
		"latitude":   coord.Latitude,
		"longitude":  coord.Longitude,
		"sequence":   seq,
		"recordedAt": rTime.Format(time.RFC3339),
	})

	return assignmentID, coord, seq, rTime.UTC().Format(time.RFC3339), nil
}

func UpdateAssignmentProgress(ctx context.Context, actorID, actorRole, assignmentID, status, occurredAt string) (string, string, string, error) {
	var sampleID string
	err := db.Pool.QueryRow(ctx, "SELECT sample_id FROM assignments WHERE id = $1", assignmentID).Scan(&sampleID)
	if err != nil {
		return "", "", "", errors.New("assignment not found")
	}

	_, err = db.Pool.Exec(ctx, "UPDATE assignments SET status = $1, updated_at = NOW() WHERE id = $2", status, assignmentID)
	if err != nil {
		return "", "", "", err
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "assignment.update_progress", "assignment", assignmentID, true, map[string]any{
		"status": status,
	})

	return assignmentID, sampleID, status, nil
}

