observation.new_content:
package service

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"backend/internal/db"
	"backend/internal/model"
)

func IsLocationStale(recAt *time.Time) bool {
	if recAt == nil {
		return true
	}
	return time.Since(*recAt) > 15*time.Minute
}

func GetJourneyPlan(ctx context.Context, journeyID string) (*model.JourneyPlan, error) {
	var p model.JourneyPlan
	var parentID, replanStatus *string
	var estDelivery *time.Time
	var valid bool
	var cost float64
	var capUsed, capAvail int

	err := db.Pool.QueryRow(ctx, `
SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, replan_status, valid
FROM journeys
WHERE id = $1;
`, journeyID).Scan(&p.JourneyId, &parentID, &p.PlanVersion, &p.RouteMode, &p.Status, &estDelivery, &cost, &capUsed, &capAvail, &replanStatus, &valid)
	if err != nil {
		return nil, err
	}

	p.ParentJourneyId = parentID
	p.ReplanStatus = replanStatus
	p.Valid = &valid
	p.TotalCostUnits = &cost
	p.CapacityUsed = &capUsed
	p.CapacityAvailable = &capAvail
	if estDelivery != nil {
		s := estDelivery.UTC().Format(time.RFC3339)
		p.EstimatedDeliveryAt = &s
	}

	// Samples
	sRows, err := db.Pool.Query(ctx, "SELECT sample_id FROM journey_samples WHERE journey_id = $1", journeyID)
	if err == nil {
		p.SampleIds = make([]string, 0)
		for sRows.Next() {
			var sid string
			if err := sRows.Scan(&sid); err == nil {
				p.SampleIds = append(p.SampleIds, sid)
			}
		}
		sRows.Close()
	}

	// Stops
	stopRows, err := db.Pool.Query(ctx, `
SELECT id, location_id, stop_type, sequence, estimated_at, completed_at, dwell_minutes, latitude, longitude
FROM journey_stops
WHERE journey_id = $1
ORDER BY sequence ASC;
`, journeyID)
	if err == nil {
		p.OrderedStops = make([]model.JourneyStop, 0)
		for stopRows.Next() {
			var js model.JourneyStop
			var estAt time.Time
			var compAt *time.Time
			var dwell *int
			var lat, lng *float64

			if err := stopRows.Scan(&js.StopId, &js.LocationId, &js.StopType, &js.Sequence, &estAt, &compAt, &dwell, &lat, &lng); err == nil {
				js.LocationIdAlt = js.LocationId
				js.StopTypeAlt = js.StopType
				js.EstimatedAt = estAt.UTC().Format(time.RFC3339)
				js.EstimatedAtAlt = js.EstimatedAt
				js.DwellMinutes = dwell
				if compAt != nil {
					s := compAt.UTC().Format(time.RFC3339)
					js.CompletedAt = &s
				}
				if lat != nil && lng != nil {
					js.Coordinate = &model.Coordinate{Latitude: *lat, Longitude: *lng}
				}
				p.OrderedStops = append(p.OrderedStops, js)
			}
		}
		stopRows.Close()
	}

	// Legs / Assignments
	assignRows, err := db.Pool.Query(ctx, `
SELECT id, sequence, status, from_location_id, to_location_id, worker_id, sample_id, kind
FROM assignments
WHERE journey_id = $1
ORDER BY sequence ASC;
`, journeyID)
	if err == nil {
		p.Legs = make([]model.JourneyLeg, 0)
		p.AssignedWorkerIds = make([]string, 0)
		p.CollectionAssignmentIds = make([]string, 0)
		p.NodeAssignmentIds = make([]string, 0)
		p.LaboratoryAssignmentIds = make([]string, 0)

		var transportLegs []string

		for assignRows.Next() {
			var leg model.JourneyLeg
			var kind string
			var fromLoc, toLoc, wID, sID *string

			if err := assignRows.Scan(&leg.AssignmentId, &leg.Sequence, &leg.Status, &fromLoc, &toLoc, &wID, &sID, &kind); err == nil {
				leg.AssignmentIdAlt = leg.AssignmentId
				leg.FromLocationId = fromLoc
				leg.FromLocationIdAlt = fromLoc
				leg.ToLocationId = toLoc
				leg.ToLocationIdAlt = toLoc
				leg.WorkerId = wID
				leg.WorkerIdAlt = wID
				leg.SampleId = sID
				p.Legs = append(p.Legs, leg)

				if wID != nil && *wID != "" {
					p.AssignedWorkerIds = append(p.AssignedWorkerIds, *wID)
				}

				switch kind {
				case "collection":
					p.CollectionAssignmentIds = append(p.CollectionAssignmentIds, leg.AssignmentId)
					if p.CollectionAssignmentId == nil {
						p.CollectionAssignmentId = &leg.AssignmentId
					}
				case "node":
					p.NodeAssignmentIds = append(p.NodeAssignmentIds, leg.AssignmentId)
				case "laboratory":
					p.LaboratoryAssignmentIds = append(p.LaboratoryAssignmentIds, leg.AssignmentId)
				case "transport":
					transportLegs = append(transportLegs, leg.AssignmentId)
				}
			}
		}
		assignRows.Close()

		if len(transportLegs) > 0 {
			p.FirstTransportAssignmentId = &transportLegs[0]
			p.FinalTransportAssignmentId = &transportLegs[len(transportLegs)-1]
			if len(transportLegs) > 2 {
				p.MiddleTransportAssignmentId = &transportLegs[1]
			}
		}
	}

	return &p, nil
}

func GetSampleState(ctx context.Context, sampleID string) (*model.SampleState, error) {
	var s model.SampleState
	var lat, lng *float64
	var reqAt, deadAt time.Time
	var recAt *time.Time
	var incomp []string
	var activeJID, targetLabID *string

	err := db.Pool.QueryRow(ctx, `
SELECT s.id, s.request_id, s.requester_id, r.origin_lat, r.origin_lng, r.origin_type, r.requested_at, r.delivery_deadline,
       s.sample_type_id, r.container_type, r.temperature_min_c, r.temperature_max_c, r.incompatible_sample_types,
       r.serviceability, s.status, s.active_journey_id, s.target_laboratory_id, s.latest_lat, s.latest_lng, s.location_recorded_at
FROM samples s
JOIN requests r ON s.request_id = r.id
WHERE s.id = $1;
`, sampleID).Scan(
		&s.SampleId, &s.RequestId, &s.RequesterId, &s.Origin.Latitude, &s.Origin.Longitude, &s.OriginType, &reqAt, &deadAt,
		&s.SampleTypeId, &s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &incomp,
		&s.Serviceability, &s.State.Status, &activeJID, &targetLabID, &lat, &lng, &recAt,
	)
	if err != nil {
		return nil, err
	}

	s.RequestedAt = reqAt.UTC().Format(time.RFC3339)
	s.DeliveryDeadline = deadAt.UTC().Format(time.RFC3339)
	s.IncompatibleSampleTypes = incomp
	if s.IncompatibleSampleTypes == nil {
		s.IncompatibleSampleTypes = []string{}
	}
	s.ActiveJourneyId = activeJID
	s.TargetLaboratoryId = targetLabID
	s.LocationStale = IsLocationStale(recAt)

	if lat != nil && lng != nil {
		s.LatestLocation = &model.Coordinate{Latitude: *lat, Longitude: *lng}
	}
	if recAt != nil {
		t := recAt.UTC().Format(time.RFC3339)
		s.LocationRecordedAt = &t
	}

	// Active assignments
	aRows, err := db.Pool.Query(ctx, `
SELECT id FROM assignments WHERE sample_id = $1 AND status IN ('offered', 'pending', 'accepted', 'in_transit', 'arrived');
`, sampleID)
	s.ActiveAssignmentIds = make([]string, 0)
	if err == nil {
		for aRows.Next() {
			var aid string
			if err := aRows.Scan(&aid); err == nil {
				s.ActiveAssignmentIds = append(s.ActiveAssignmentIds, aid)
			}
		}
		aRows.Close()
	}

	// Timeline
	timeline, _ := GetTimelineForEntity(ctx, "sample", sampleID)
	if timeline == nil {
		timeline = []model.TimelineEntry{}
	}
	s.Timeline = timeline

	return &s, nil
}

func GetSampleLifecycle(ctx context.Context, sampleID string) (*model.SampleLifecycle, error) {
	var sl model.SampleLifecycle
	var currentHolder, activeJID, recvLab *string
	var excJSON []byte
	var lat, lng *float64
	var recAt *time.Time

	err := db.Pool.QueryRow(ctx, `
SELECT id, status, sealed, current_holder_id, active_journey_id, received_laboratory_id, exception_details, latest_lat, latest_lng, location_recorded_at
FROM samples
WHERE id = $1;
`, sampleID).Scan(&sl.SampleId, &sl.Status, &sl.Sealed, &currentHolder, &activeJID, &recvLab, &excJSON, &lat, &lng, &recAt)
	if err != nil {
		return nil, err
	}

	sl.CurrentHolderId = currentHolder
	sl.ActiveJourneyId = activeJID
	sl.ReceivedLaboratoryId = recvLab
	sl.LocationStale = IsLocationStale(recAt)

	if len(excJSON) > 0 {
		_ = json.Unmarshal(excJSON, &sl.Exception)
	}

	if lat != nil && lng != nil {
		sl.LatestLocation = &model.Coordinate{Latitude: *lat, Longitude: *lng}
	}
	if recAt != nil {
		t := recAt.UTC().Format(time.RFC3339)
		sl.LocationRecordedAt = &t
	}

	// Completed legs
	sl.CompletedLegIds = make([]string, 0)
	cRows, err := db.Pool.Query(ctx, "SELECT id FROM assignments WHERE sample_id = $1 AND status = 'completed'", sampleID)
	if err == nil {
		for cRows.Next() {
			var aid string
			if err := cRows.Scan(&aid); err == nil {
				sl.CompletedLegIds = append(sl.CompletedLegIds, aid)
			}
		}
		cRows.Close()
	}

	sl.ActiveReplacementPlanIds = []string{}

	// Pending handoff
	var hID, hSender, hReceiver string
	var hSenderConf, hReceiverConf bool
	err = db.Pool.QueryRow(ctx, `
SELECT id, sender_id, receiver_id, sender_confirmed, receiver_confirmed
FROM handoffs
WHERE sample_id = $1 AND status = 'pending'
LIMIT 1;
`, sampleID).Scan(&hID, &hSender, &hReceiver, &hSenderConf, &hReceiverConf)
	if err == nil {
		sl.PendingHandoffId = &hID
		sl.PendingHandoff = map[string]any{
			"handoffId":        hID,
			"senderId":         hSender,
			"receiverId":       hReceiver,
			"senderConfirmed":  hSenderConf,
			"receiverConfirmed": hReceiverConf,
		}
	}

	timeline, _ := GetTimelineForEntity(ctx, "sample", sampleID)
	if timeline == nil {
		timeline = []model.TimelineEntry{}
	}
	sl.Timeline = timeline

	return &sl, nil
}

func ListRoleWork(ctx context.Context, userID, activeRole string, filterStatus *string) (*model.RoleWork, error) {
	res := &model.RoleWork{
		Pending:    make([]any, 0),
		InProgress: make([]any, 0),
		Completed:  make([]any, 0),
	}

	if activeRole == "requester" {
		rows, err := db.Pool.Query(ctx, `
SELECT s.id, s.request_id, s.status, r.serviceability, r.requested_at, r.delivery_deadline,
       r.earliest_collection_at, r.latest_collection_at, s.active_journey_id, s.target_laboratory_id,
       s.current_holder_id, s.requester_id, s.location_recorded_at
FROM samples s
JOIN requests r ON s.request_id = r.id
WHERE s.requester_id = $1
ORDER BY s.created_at DESC;
`, userID)
		if err != nil {
			return res, err
		}
		defer rows.Close()

		for rows.Next() {
			var w model.SampleWorkItem
			w.Kind = "sample"
			var reqAt, deadAt, earAt, latAt time.Time
			var actJID, targetLab, currHold, reqID *string
			var recAt *time.Time
			var srv *string

			if err := rows.Scan(&w.SampleId, &w.RequestId, &w.Status, &srv, &reqAt, &deadAt, &earAt, &latAt, &actJID, &targetLab, &currHold, &reqID, &recAt); err == nil {
				w.SampleIdAlt = w.SampleId
				w.Serviceability = srv
				sReq := reqAt.UTC().Format(time.RFC3339)
				w.RequestedAt = &sReq
				sDead := deadAt.UTC().Format(time.RFC3339)
				w.DeliveryDeadline = &sDead
				sEar := earAt.UTC().Format(time.RFC3339)
				w.EarliestCollectionAt = &sEar
				sLat := latAt.UTC().Format(time.RFC3339)
				w.LatestCollectionAt = &sLat
				w.ActiveJourneyId = actJID
				w.JourneyId = actJID
				w.LaboratoryId = targetLab
				w.CurrentHolderId = currHold
				w.RequesterId = reqID
				w.LocationStale = IsLocationStale(recAt)
				if recAt != nil {
					t := recAt.UTC().Format(time.RFC3339)
					w.LocationRecordedAt = &t
				}

				hist, _ := GetTimelineForEntity(ctx, "sample", w.SampleId)
				if hist == nil {
					hist = []model.TimelineEntry{}
				}
				w.History = hist

				if w.Status == "requested" || w.Status == "pending" || w.Status == "offered" {
					res.Pending = append(res.Pending, w)
				} else if w.Status == "received" || w.Status == "completed" || w.Status == "cancelled" || w.Status == "expired" {
					res.Completed = append(res.Completed, w)
				} else {
					res.InProgress = append(res.InProgress, w)
				}
			}
		}
		return res, nil
	}

	if activeRole == "dispatcher" || activeRole == "administrator" {
		rows, err := db.Pool.Query(ctx, `
SELECT id, status, route_mode, plan_version, estimated_delivery_at,
       (SELECT COUNT(*) FROM assignments a WHERE a.journey_id = j.id) as assign_count
FROM journeys j
ORDER BY j.created_at DESC;
`)
		if err != nil {
			return res, err
		}
		defer rows.Close()

		for rows.Next() {
			var w model.JourneyWorkItem
			w.Kind = "journey"
			var estDel *time.Time

			if err := rows.Scan(&w.JourneyId, &w.Status, &w.RouteMode, &w.PlanVersion, &estDel, &w.AssignmentCount); err == nil {
				w.JourneyIdAlt = w.JourneyId
				if estDel != nil {
					w.EstimatedDeliveryAt = estDel.UTC().Format(time.RFC3339)
				}
				w.SampleIds = make([]string, 0)
				sRows, err := db.Pool.Query(ctx, "SELECT sample_id FROM journey_samples WHERE journey_id = $1", w.JourneyId)
				if err == nil {
					for sRows.Next() {
						var sid string
						if err := sRows.Scan(&sid); err == nil {
							w.SampleIds = append(w.SampleIds, sid)
						}
					}
					sRows.Close()
				}

				hist, _ := GetTimelineForEntity(ctx, "journey", w.JourneyId)
				if hist == nil {
					hist = []model.TimelineEntry{}
				}
				w.History = hist

				if w.Status == "active" || w.Status == "in_progress" {
					res.InProgress = append(res.InProgress, w)
				} else if w.Status == "completed" || w.Status == "cancelled" || w.Status == "merged" {
					res.Completed = append(res.Completed, w)
				} else {
					res.Pending = append(res.Pending, w)
				}
			}
		}
		return res, nil
	}

	// Worker roles: collection_professional, delivery_partner, node_handler, laboratory_team
	targetKind := ""
	switch activeRole {
	case "collection_professional":
		targetKind = "collection"
	case "delivery_partner":
		targetKind = "transport"
	case "node_handler":
		targetKind = "node"
	case "laboratory_team":
		targetKind = "laboratory"
	}

	rows, err := db.Pool.Query(ctx, `
SELECT a.id, a.sample_id, a.status, a.journey_id, a.from_location_id, a.to_location_id,
       a.sequence, a.offer_expires_at, a.node_id, a.laboratory_id, a.expected_sample_type_id,
       a.worker_id, a.offered_worker_id
FROM assignments a
WHERE a.kind = $1 AND (a.worker_id = $2 OR a.offered_worker_id = $2 OR
      (a.node_id IS NOT NULL AND a.node_id = (SELECT assigned_location_id FROM users WHERE id = $2)) OR
      (a.laboratory_id IS NOT NULL AND a.laboratory_id = (SELECT assigned_location_id FROM users WHERE id = $2)))
ORDER BY a.created_at DESC;
`, targetKind, userID)
	if err != nil {
		return res, err
	}
	defer rows.Close()

	for rows.Next() {
		var w model.AssignmentWorkItem
		w.Kind = targetKind
		var jID, fromLoc, toLoc, nID, lID, expST, wID, offWID *string
		var seq *int
		var offExp *time.Time

		if err := rows.Scan(&w.AssignmentId, &w.SampleId, &w.Status, &jID, &fromLoc, &toLoc, &seq, &offExp, &nID, &lID, &expST, &wID, &offWID); err == nil {
			w.AssignmentIdAlt = w.AssignmentId
			w.SampleIdAlt = w.SampleId
			w.JourneyId = jID
			w.FromLocationId = fromLoc
			w.ToLocationId = toLoc
			w.Sequence = seq
			if offExp != nil {
				s := offExp.UTC().Format(time.RFC3339)
				w.OfferExpiresAt = &s
			}
			w.NodeId = nID
			w.IncomingFromLocationId = fromLoc
			w.OutgoingToLocationId = toLoc
			w.LaboratoryId = lID
			w.ExpectedSampleTypeId = expST

			hist, _ := GetTimelineForEntity(ctx, "assignment", w.AssignmentId)
			if hist == nil {
				hist = []model.TimelineEntry{}
			}
			w.History = hist

			if w.Status == "offered" || w.Status == "pending" {
				res.Pending = append(res.Pending, w)
			} else if w.Status == "completed" || w.Status == "cancelled" || w.Status == "declined" {
				res.Completed = append(res.Completed, w)
			} else {
				res.InProgress = append(res.InProgress, w)
			}
		}
	}

	return res, nil
}

func ReadOperationsState(ctx context.Context) (*model.OperationsState, error) {
	st := &model.OperationsState{
		Samples:                   make([]model.OperationsSample, 0),
		Workers:                   make([]model.OperationsWorker, 0),
		Locations:                 make([]model.OperationsLocation, 0),
		Connections:               make([]model.OperationsConnection, 0),
		Routes:                    make([]map[string]any, 0),
		Handoffs:                  make([]map[string]any, 0),
		Delays:                    make([]map[string]any, 0),
		Exceptions:                make([]map[string]any, 0),
		AssignmentCountSpread:     0,
		IneligibleAssignmentCount: 0,
	}

	// 1. Samples
	sRows, err := db.Pool.Query(ctx, `
SELECT s.id, s.status, s.request_id, r.origin_lat, r.origin_lng, r.delivery_deadline,
       s.current_holder_id, s.active_journey_id, s.latest_lat, s.latest_lng, s.location_recorded_at
FROM samples s
JOIN requests r ON s.request_id = r.id
ORDER BY s.created_at DESC;
`)
	if err == nil {
		for sRows.Next() {
			var os model.OperationsSample
			var reqID, currHolder, actJID *string
			var oLat, oLng, lLat, lLng *float64
			var dDead *time.Time
			var recAt *time.Time

			if err := sRows.Scan(&os.SampleId, &os.Status, &reqID, &oLat, &oLng, &dDead, &currHolder, &actJID, &lLat, &lLng, &recAt); err == nil {
				os.SampleIdAlt = os.SampleId
				os.RequestId = reqID
				if oLat != nil && oLng != nil {
					os.Origin = &model.Coordinate{Latitude: *oLat, Longitude: *oLng}
				}
				if dDead != nil {
					s := dDead.UTC().Format(time.RFC3339)
					os.DeliveryDeadline = &s
				}
				os.CurrentHolderId = currHolder
				os.ActiveJourneyId = actJID
				if lLat != nil && lLng != nil {
					os.LatestLocation = &model.Coordinate{Latitude: *lLat, Longitude: *lLng}
				}
				if recAt != nil {
					s := recAt.UTC().Format(time.RFC3339)
					os.LocationRecordedAt = &s
				}
				os.LocationStale = IsLocationStale(recAt)
				st.Samples = append(st.Samples, os)
			}
		}
		sRows.Close()
	}

	// 2. Workers
	wRows, err := db.Pool.Query(ctx, `
SELECT u.id, u.full_name, u.roles, u.available, u.capacity_units,
       (SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status IN ('accepted', 'in_transit', 'arrived')) as assign_count,
       u.latitude, u.longitude, u.location_recorded_at
FROM users u
WHERE 'collection_professional' = ANY(u.roles) OR 'delivery_partner' = ANY(u.roles) OR 'node_handler' = ANY(u.roles) OR 'laboratory_team' = ANY(u.roles);
`)
	minAssign := 999999
	maxAssign := 0
	if err == nil {
		for wRows.Next() {
			var ow model.OperationsWorker
			var fName *string
			var lat, lng *float64
			var recAt *time.Time

			if err := wRows.Scan(&ow.WorkerId, &fName, &ow.Roles, &ow.Available, &ow.CapacityUnits, &ow.AssignmentCount, &lat, &lng, &recAt); err == nil {
				ow.WorkerIdAlt = ow.WorkerId
				ow.FullName = fName
				ow.Status = "available"
				if !ow.Available {
					ow.Status = "unavailable"
				}
				if lat != nil && lng != nil {
					ow.LatestLocation = &model.Coordinate{Latitude: *lat, Longitude: *lng}
					ow.LatestLocationAlt = ow.LatestLocation
				}
				if recAt != nil {
					s := recAt.UTC().Format(time.RFC3339)
					ow.LocationRecordedAt = &s
				}
				ow.LocationStale = IsLocationStale(recAt)

				if ow.AssignmentCount < minAssign {
					minAssign = ow.AssignmentCount
				}
				if ow.AssignmentCount > maxAssign {
					maxAssign = ow.AssignmentCount
				}

				st.Workers = append(st.Workers, ow)
			}
		}
		wRows.Close()
	}
	if len(st.Workers) > 0 && maxAssign >= minAssign {
		st.AssignmentCountSpread = maxAssign - minAssign
	}

	// 3. Locations
	lRows, err := db.Pool.Query(ctx, `
SELECT id, name, latitude, longitude, active, coverage_km, handling_minutes,
       is_collection_point, is_transfer_point, is_hub, is_laboratory,
       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM locations;
`)
	if err == nil {
		for lRows.Next() {
			var ol model.OperationsLocation
			var isCP, isTP, isHub, isLab bool
			var capU, resU, cCapU, cResU int

			if err := lRows.Scan(&ol.LocationId, &ol.Name, &ol.Coordinate.Latitude, &ol.Coordinate.Longitude, &ol.Active, &ol.CoverageKm, &ol.HandlingMinutes, &isCP, &isTP, &isHub, &isLab, &capU, &resU, &cCapU, &cResU); err == nil {
				ol.ID = ol.LocationId
				ol.Functions = model.LocationFunctionStates{
					CollectionPoint: &isCP,
					TransferPoint:   &isTP,
					Hub:             &isHub,
					Laboratory:      &isLab,
				}
				ol.Capacity = &model.Capacity{
					CapacityUnits:        capU,
					ReservedUnits:        resU,
					AvailableUnits:       capU - resU,
					CooledCapacityUnits:  cCapU,
					CooledReservedUnits:  cResU,
					CooledAvailableUnits: cCapU - cResU,
				}

				// Accepted sample types for lab
				if isLab {
					ol.AcceptedSampleTypeIds = make([]string, 0)
					laRows, err := db.Pool.Query(ctx, "SELECT sample_type_id FROM laboratory_acceptance WHERE laboratory_id = $1 AND accepts = true", ol.LocationId)
					if err == nil {
						for laRows.Next() {
							var stid string
							if err := laRows.Scan(&stid); err == nil {
								ol.AcceptedSampleTypeIds = append(ol.AcceptedSampleTypeIds, stid)
							}
						}
						laRows.Close()
					}
				}

				st.Locations = append(st.Locations, ol)
			}
		}
		lRows.Close()
	}

	// 4. Connections
	cRows, err := db.Pool.Query(ctx, `
SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
FROM connections;
`)
	if err == nil {
		for cRows.Next() {
			var oc model.OperationsConnection
			var capU, resU, cCapU, cResU int

			if err := cRows.Scan(&oc.ConnectionId, &oc.FromLocationId, &oc.ToLocationId, &oc.TravelMinutes, &oc.CostUnits, &oc.Cooled, &oc.Active, &capU, &resU, &cCapU, &cResU); err == nil {
				oc.ID = oc.ConnectionId
				oc.Capacity = &model.Capacity{
					CapacityUnits:        capU,
					ReservedUnits:        resU,
					AvailableUnits:       capU - resU,
					CooledCapacityUnits:  cCapU,
					CooledReservedUnits:  cResU,
					CooledAvailableUnits: cCapU - cResU,
				}
				st.Connections = append(st.Connections, oc)
			}
		}
		cRows.Close()
	}

	// 5. Handoffs
	hRows, err := db.Pool.Query(ctx, `
SELECT id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, current_holder_id, status, sender_confirmed, receiver_confirmed
FROM handoffs
ORDER BY created_at DESC;
`)
	if err == nil {
		for hRows.Next() {
			var hid, sid, sID, rID, chID, stat string
			var fromAID, toAID *string
			var sConf, rConf bool
			if err := hRows.Scan(&hid, &sid, &fromAID, &toAID, &sID, &rID, &chID, &stat, &sConf, &rConf); err == nil {
				st.Handoffs = append(st.Handoffs, map[string]any{
					"handoffId":        hid,
					"sampleId":         sid,
					"fromAssignmentId": fromAID,
					"toAssignmentId":   toAID,
					"senderId":         sID,
					"receiverId":       rID,
					"currentHolderId":  chID,
					"status":           stat,
					"senderConfirmed":  sConf,
					"receiverConfirmed": rConf,
				})
			}
		}
		hRows.Close()
	}

	// 6. Exceptions
	eRows, err := db.Pool.Query(ctx, `
SELECT id, status, exception_details
FROM samples
WHERE status = 'exception' OR exception_details IS NOT NULL;
`)
	if err == nil {
		for eRows.Next() {
			var sid, stat string
			var excJSON []byte
			if err := eRows.Scan(&sid, &stat, &excJSON); err == nil {
				var excMap map[string]any
				if len(excJSON) > 0 {
					_ = json.Unmarshal(excJSON, &excMap)
				}
				if excMap == nil {
					excMap = make(map[string]any)
				}
				excMap["sampleId"] = sid
				excMap["status"] = stat
				st.Exceptions = append(st.Exceptions, excMap)
			}
		}
		eRows.Close()
	}

	return st, nil
}

type SearchAuditInput struct {
	Query      *string `json:"query"`
	ActorId    *string `json:"actorId"`
	EntityType *string `json:"entityType"`
	EntityId   *string `json:"entityId"`
	Action     *string `json:"action"`
	Role       *string `json:"role"`
	Success    *bool   `json:"success"`
	FromTime   *string `json:"fromTime"`
	ToTime     *string `json:"toTime"`
	Limit      *int    `json:"limit"`
	Offset     *int    `json:"offset"`
	Order      *string `json:"order"`
}

func SearchAuditTrail(ctx context.Context, in SearchAuditInput) (*model.AuditSearchResult, error) {
	limit := 50
	if in.Limit != nil && *in.Limit > 0 {
		limit = *in.Limit
	}
	offset := 0
	if in.Offset != nil && *in.Offset >= 0 {
		offset = *in.Offset
	}
	order := "newest_first"
	if in.Order != nil && *in.Order == "oldest_first" {
		order = "oldest_first"
	}

	orderClause := "ORDER BY occurred_at DESC, id DESC"
	if order == "oldest_first" {
		orderClause = "ORDER BY occurred_at ASC, id ASC"
	}

	where := "WHERE 1=1"
	args := make([]any, 0)
	argIdx := 1

	if in.ActorId != nil && *in.ActorId != "" {
		where += fmt.Sprintf(" AND actor_id = $%d", argIdx)
		args = append(args, *in.ActorId)
		argIdx++
	}
	if in.EntityType != nil && *in.EntityType != "" {
		where += fmt.Sprintf(" AND entity_type = $%d", argIdx)
		args = append(args, *in.EntityType)
		argIdx++
	}
	if in.EntityId != nil && *in.EntityId != "" {
		where += fmt.Sprintf(" AND entity_id = $%d", argIdx)
		args = append(args, *in.EntityId)
		argIdx++
	}
	if in.Action != nil && *in.Action != "" {
		where += fmt.Sprintf(" AND action = $%d", argIdx)
		args = append(args, *in.Action)
		argIdx++
	}
	if in.Role != nil && *in.Role != "" {
		where += fmt.Sprintf(" AND role = $%d", argIdx)
		args = append(args, *in.Role)
		argIdx++
	}
	if in.Success != nil {
		where += fmt.Sprintf(" AND success = $%d", argIdx)
		args = append(args, *in.Success)
		argIdx++
	}
	if in.FromTime != nil && *in.FromTime != "" {
		if t, err := time.Parse(time.RFC3339, *in.FromTime); err == nil {
			where += fmt.Sprintf(" AND occurred_at >= $%d", argIdx)
			args = append(args, t)
			argIdx++
		}
	}
	if in.ToTime != nil && *in.ToTime != "" {
		if t, err := time.Parse(time.RFC3339, *in.ToTime); err == nil {
			where += fmt.Sprintf(" AND occurred_at <= $%d", argIdx)
			args = append(args, t)
			argIdx++
		}
	}
	if in.Query != nil && *in.Query != "" {
		where += fmt.Sprintf(" AND (action ILIKE $%d OR entity_type ILIKE $%d OR details::text ILIKE $%d)", argIdx, argIdx, argIdx)
		args = append(args, "%"+*in.Query+"%")
		argIdx++
	}

	var total int
	countQuery := "SELECT COUNT(*) FROM audit_entries " + where
	_ = db.Pool.QueryRow(ctx, countQuery, args...).Scan(&total)

	dataQuery := fmt.Sprintf("SELECT audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details FROM audit_entries %s %s LIMIT %d OFFSET %d", where, orderClause, limit, offset)
	rows, err := db.Pool.Query(ctx, dataQuery, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	entries := make([]model.AuditEntry, 0)
	for rows.Next() {
		var e model.AuditEntry
		var occAt time.Time
		var dJSON []byte
		if err := rows.Scan(&e.AuditId, &e.ActorId, &e.Role, &e.ActorRole, &e.Action, &e.EntityType, &e.EntityId, &e.Success, &occAt, &dJSON); err == nil {
			e.AuditIdAlt = e.AuditId
			e.ActorIdAlt = e.ActorId
			e.EntityTypeAlt = e.EntityType
			e.EntityIdAlt = e.EntityId
			e.OccurredAt = occAt.UTC().Format(time.RFC3339)
			e.OccurredAtAlt = e.OccurredAt
			_ = json.Unmarshal(dJSON, &e.Details)
			if e.Details == nil {
				e.Details = make(map[string]any)
			}
			entries = append(entries, e)
		}
	}

	hasMore := offset+len(entries) < total
	var nextOffset *int
	if hasMore {
		no := offset + len(entries)
		nextOffset = &no
	}

	return &model.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}, nil
}

