// Check if idempotency key exists
func checkIdempotency(ctx context.Context, key *string) (bool, int, map[string]any) {
	if key == nil || *key == "" {
		return false, 0, nil
	}
	var status int
	var bodyJSON []byte
	err := db.Pool.QueryRow(ctx, "SELECT response_status, response_body FROM idempotency_keys WHERE key = $1", *key).Scan(&status, &bodyJSON)
	if err == nil {
		var res map[string]any
		_ = json.Unmarshal(bodyJSON, &res)
		return true, status, res
	}
	return false, 0, nil
}

func saveIdempotency(ctx context.Context, key *string, status int, data any) {
	if key == nil || *key == "" {
		return
	}
	bodyJSON, _ := json.Marshal(data)
	_, _ = db.Pool.Exec(ctx, "INSERT INTO idempotency_keys (key, response_status, response_body) VALUES ($1, $2, $3) ON CONFLICT (key) DO NOTHING", *key, status, bodyJSON)
}

// 1. Ready
func (rt *Router) HandleReady(w http.ResponseWriter, r *http.Request) {
	if err := db.Pool.Ping(r.Context()); err != nil {
		rt.WriteJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "not_ready"})
		return
	}
	rt.WriteJSON(w, http.StatusOK, map[string]string{"status": "ready"})
}

// 2. Authenticate
func (rt *Router) HandleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		rt.WriteError(w, http.StatusBadRequest, "invalid request body", "BAD_REQUEST")
		return
	}

	token, u, err := service.AuthenticateUser(r.Context(), req.Username, req.Password)
	if err != nil {
		rt.WriteError(w, http.StatusUnauthorized, err.Error(), "UNAUTHORIZED")
		return
	}

	rt.WriteJSON(w, http.StatusOK, map[string]any{
		"data": map[string]any{
			"sessionToken": token,
			"userId":       u.UserId,
			"roles":        u.Roles,
			"activeRole":   u.ActiveRole,
		},
	})
}

