// 7. Set Worker Availability
func (rt *Router) HandleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	claims := GetClaims(r)
	var req struct {
		WorkerId      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		rt.WriteError(w, http.StatusBadRequest, "invalid request body", "BAD_REQUEST")
		return
	}

	if claims.ActiveRole != "administrator" && claims.ActiveRole != "dispatcher" && claims.UserId != req.WorkerId {
		rt.WriteError(w, http.StatusForbidden, "forbidden", "FORBIDDEN")
		return
	}

	if err := service.SetWorkerAvailability(r.Context(), claims.UserId, claims.ActiveRole, req.WorkerId, req.Available, req.CapacityUnits); err != nil {
		rt.WriteError(w, http.StatusBadRequest, err.Error(), "BAD_REQUEST")
		return
	}

	rt.WriteJSON(w, http.StatusOK, map[string]any{
		"data": map[string]any{
			"workerId":      req.WorkerId,
			"available":     req.Available,
			"capacityUnits": req.CapacityUnits,
		},
	})
}

