// 20. Create Collection Request
func (rt *Router) HandleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	claims := GetClaims(r)
	var in service.CreateCollectionRequestInput
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		rt.WriteError(w, http.StatusBadRequest, "invalid request body", "BAD_REQUEST")
		return
	}

	if seen, status, resp := checkIdempotency(r.Context(), in.IdempotencyKey); seen {
		rt.WriteJSON(w, status, resp)
		return
	}

	res, err := service.CreateCollectionRequest(r.Context(), claims.UserId, claims.ActiveRole, in, false)
	if err != nil {
		rt.WriteError(w, http.StatusBadRequest, err.Error(), "BAD_REQUEST")
		return
	}

	out := map[string]any{"data": res}
	saveIdempotency(r.Context(), in.IdempotencyKey, http.StatusCreated, out)
	rt.WriteJSON(w, http.StatusCreated, out)
}

