func (rt *Router) HandleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	claims := GetClaims(r)
	var req struct {
		JourneyId string `json:"journeyId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		rt.WriteError(w, http.StatusBadRequest, "invalid request body", "BAD_REQUEST")
		return
	}

	plan, err := service.GetJourneyPlan(r.Context(), req.JourneyId)
	if err != nil {
		rt.WriteError(w, http.StatusNotFound, "journey not found", "NOT_FOUND")
		return
	}

	if claims.ActiveRole == "requester" {
		reqPlan := model.RequesterJourneyPlan{
			JourneyId:           plan.JourneyId,
			ParentJourneyId:     plan.ParentJourneyId,
			PlanVersion:         &plan.PlanVersion,
			RouteMode:           &plan.RouteMode,
			Status:              &plan.Status,
			EstimatedDeliveryAt: plan.EstimatedDeliveryAt,
			TotalCostUnits:      plan.TotalCostUnits,
			SampleIds:           plan.SampleIds,
			OrderedStops:        plan.OrderedStops,
			Legs:                make([]any, len(plan.Legs)),
		}
		for i, l := range plan.Legs {
			reqPlan.Legs[i] = l
		}
		rt.WriteJSON(w, http.StatusOK, map[string]any{"data": reqPlan})
		return
	}

	if claims.ActiveRole == "delivery_partner" || claims.ActiveRole == "collection_professional" || claims.ActiveRole == "node_handler" || claims.ActiveRole == "laboratory_team" {
		wPlan := model.WorkerJourneyPlan{
			JourneyId:               plan.JourneyId,
			ParentJourneyId:         plan.ParentJourneyId,
			PlanVersion:             plan.PlanVersion,
			RouteMode:               plan.RouteMode,
			Status:                  plan.Status,
			EstimatedDeliveryAt:     plan.EstimatedDeliveryAt,
			Scope:                   "assigned_legs",
			AssignmentIds:           make([]string, 0),
			SampleIds:               plan.SampleIds,
			Legs:                    make([]model.JourneyLeg, 0),
			OrderedStops:            plan.OrderedStops,
			CollectionAssignmentIds: plan.CollectionAssignmentIds,
			NodeAssignmentIds:       plan.NodeAssignmentIds,
			LaboratoryAssignmentIds: plan.LaboratoryAssignmentIds,
			AssignedWorkerIds:       plan.AssignedWorkerIds,
		}
		for _, l := range plan.Legs {
			if l.WorkerId != nil && *l.WorkerId == claims.UserId {
				wPlan.AssignmentIds = append(wPlan.AssignmentIds, l.AssignmentId)
				wPlan.Legs = append(wPlan.Legs, l)
			}
		}
		if len(wPlan.AssignmentIds) == 0 {
			// If not assigned yet, include legs offered to this worker
			for _, l := range plan.Legs {
				wPlan.AssignmentIds = append(wPlan.AssignmentIds, l.AssignmentId)
				wPlan.Legs = append(wPlan.Legs, l)
			}
		}
		rt.WriteJSON(w, http.StatusOK, map[string]any{"data": wPlan})
		return
	}

	rt.WriteJSON(w, http.StatusOK, map[string]any{"data": plan})
}

