// 44. UI Bootstrap
func (rt *Router) HandleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	claims := GetClaims(r)
	u, err := service.GetUserByID(r.Context(), claims.UserId)
	if err != nil {
		rt.WriteError(w, http.StatusNotFound, "user not found", "NOT_FOUND")
		return
	}

	ops, _ := service.ReadOperationsState(r.Context())

	// Requester samples
	requesterSamples := make([]map[string]any, 0)
	if claims.ActiveRole == "requester" {
		rows, err := db.Pool.Query(r.Context(), "SELECT id FROM samples WHERE requester_id = $1", claims.UserId)
		if err == nil {
			for rows.Next() {
				var sid string
				if err := rows.Scan(&sid); err == nil {
					st, _ := service.GetSampleState(r.Context(), sid)
					if st != nil {
						b, _ := json.Marshal(st)
						var m map[string]any
						_ = json.Unmarshal(b, &m)
						requesterSamples = append(requesterSamples, m)
					}
				}
			}
			rows.Close()
		}
	}

	rt.WriteJSON(w, http.StatusOK, map[string]any{
		"data": map[string]any{
			"user": map[string]any{
				"userId":                u.UserId,
				"username":              u.Username,
				"fullName":              u.FullName,
				"roles":                 u.Roles,
				"activeRole":            u.ActiveRole,
				"roleSelectionRequired": len(u.Roles) > 1 && u.ActiveRole == "",
			},
			"serverTime":       time.Now().UTC().Format(time.RFC3339),
			"requesterSamples": requesterSamples,
			"operations":       ops,
		},
	})
}

// 45. Realtime Events Stream (WebSocket or Long Polling / SSE)
func (rt *Router) HandleEvents(w http.ResponseWriter, r *http.Request) {
	if websocket.IsWebSocketUpgrade(r) {
		conn, err := rt.upgrader.Upgrade(w, r, nil)
		if err != nil {
			return
		}
		defer conn.Close()

		ch := service.Hub.Subscribe()
		defer service.Hub.Unsubscribe(ch)

		for ev := range ch {
			if err := conn.WriteJSON(ev); err != nil {
				break
			}
		}
		return
	}

	// HTTP query mode with ?since=
	sinceStr := r.URL.Query().Get("since")
	var sinceID int64 = 0
	if sinceStr != "" {
		_ = json.Unmarshal([]byte(sinceStr), &sinceID)
	}

	rows, err := db.Pool.Query(r.Context(), `
SELECT id, type, entity_type, entity_id, payload, created_at
FROM realtime_events
WHERE id > $1
ORDER BY id ASC
LIMIT 100;
`, sinceID)
	if err != nil {
		rt.WriteError(w, http.StatusInternalServerError, err.Error(), "INTERNAL_ERROR")
		return
	}
	defer rows.Close()

	events := make([]model.RealtimeEvent, 0)
	maxID := sinceID
	for rows.Next() {
		var ev model.RealtimeEvent
		var plJSON []byte
		var cAt time.Time
		if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityId, &plJSON, &cAt); err == nil {
			_ = json.Unmarshal(plJSON, &ev.Payload)
			if ev.Payload == nil {
				ev.Payload = make(map[string]any)
			}
			ev.CreatedAt = cAt.UTC().Format(time.RFC3339)
			events = append(events, ev)
			if ev.ID > maxID {
				maxID = ev.ID
			}
		}
	}

	rt.WriteJSON(w, http.StatusOK, map[string]any{
		"data": map[string]any{
			"events": events,
			"cursor": maxID,
		},
	})
}

