package handler

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"backend/internal/db"
	"backend/internal/model"
	"backend/internal/service"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
)

type Router struct {
	upgrader websocket.Upgrader
}

func NewRouter() *Router {
	return &Router{
		upgrader: websocket.Upgrader{
			CheckOrigin: func(r *http.Request) bool { return true },
		},
	}
}

type contextKey string

const userContextKey contextKey = "userClaims"

func (rt *Router) WriteJSON(w http.ResponseWriter, statusCode int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(statusCode)
	_ = json.NewEncoder(w).Encode(data)
}

func (rt *Router) WriteError(w http.ResponseWriter, statusCode int, errStr, code string) {
	rt.WriteJSON(w, statusCode, model.ErrorEnvelope{
		Error: errStr,
		Code:  code,
	})
}

func (rt *Router) AuthMiddleware(next http.HandlerFunc, allowedRoles ...string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" || !strings.HasPrefix(authHeader, "Bearer ") {
			// Also check query param or cookie if needed
			tokenParam := r.URL.Query().Get("token")
			if tokenParam != "" {
				authHeader = "Bearer " + tokenParam
			} else {
				rt.WriteError(w, http.StatusUnauthorized, "missing authorization header", "UNAUTHORIZED")
				return
			}
		}

		tokenStr := strings.TrimPrefix(authHeader, "Bearer ")
		claims, err := service.ValidateToken(tokenStr)
		if err != nil {
			rt.WriteError(w, http.StatusUnauthorized, "invalid or expired token", "UNAUTHORIZED")
			return
		}

		if len(allowedRoles) > 0 {
			roleAllowed := false
			for _, ar := range allowedRoles {
				if ar == claims.ActiveRole || ar == "*" {
					roleAllowed = true
					break
				}
			}
			if !roleAllowed {
				rt.WriteError(w, http.StatusForbidden, "action forbidden for current active role", "FORBIDDEN")
				return
			}
		}

		ctx := context.WithValue(r.Context(), userContextKey, claims)
		next(w, r.WithContext(ctx))
	}
}

func GetClaims(r *http.Request) *service.Claims {
	if c, ok := r.Context().Value(userContextKey).(*service.Claims); ok {
		return c
	}
	return nil
}

func (rt *Router) RegisterRoutes(mux *http.ServeMux) {
	// Ready endpoint
	mux.HandleFunc("GET /ready", rt.HandleReady)

	// Auth endpoints
	mux.HandleFunc("POST /api/authenticate-user", rt.HandleAuthenticateUser)
	mux.HandleFunc("POST /api/select-active-role", rt.AuthMiddleware(rt.HandleSelectActiveRole))
	mux.HandleFunc("GET /api/read-user/{userId}", rt.AuthMiddleware(rt.HandleReadUser))
	mux.HandleFunc("POST /api/create-user", rt.AuthMiddleware(rt.HandleCreateUser, "administrator"))
	mux.HandleFunc("POST /api/update-user-access", rt.AuthMiddleware(rt.HandleUpdateUserAccess, "administrator"))
	mux.HandleFunc("POST /api/set-worker-availability", rt.AuthMiddleware(rt.HandleSetWorkerAvailability))

	// Serviceability & Network
	mux.HandleFunc("POST /api/check-serviceability", rt.AuthMiddleware(rt.HandleCheckServiceability))
	mux.HandleFunc("POST /api/read-serviceability-snapshot", rt.AuthMiddleware(rt.HandleReadServiceabilitySnapshot))
	mux.HandleFunc("POST /api/create-location", rt.AuthMiddleware(rt.HandleCreateLocation, "administrator"))
	mux.HandleFunc("POST /api/update-location", rt.AuthMiddleware(rt.HandleUpdateLocation, "administrator"))
	mux.HandleFunc("POST /api/set-location-status", rt.AuthMiddleware(rt.HandleSetLocationStatus, "administrator", "dispatcher"))
	mux.HandleFunc("POST /api/set-location-function-status", rt.AuthMiddleware(rt.HandleSetLocationFunctionStatus, "administrator"))
	mux.HandleFunc("POST /api/create-connection", rt.AuthMiddleware(rt.HandleCreateConnection, "administrator"))
	mux.HandleFunc("POST /api/set-connection-status", rt.AuthMiddleware(rt.HandleSetConnectionStatus, "administrator", "dispatcher"))
	mux.HandleFunc("POST /api/configure-capacity", rt.AuthMiddleware(rt.HandleConfigureCapacity, "administrator", "dispatcher", "node_handler", "laboratory_team"))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", rt.AuthMiddleware(rt.HandleConfigureLaboratoryAcceptance, "administrator"))
	mux.HandleFunc("POST /api/create-sample-type", rt.AuthMiddleware(rt.HandleCreateSampleType, "administrator"))
	mux.HandleFunc("POST /api/update-sample-type", rt.AuthMiddleware(rt.HandleUpdateSampleType, "administrator"))

	// Requests & Ingestion
	mux.HandleFunc("POST /api/create-collection-request", rt.AuthMiddleware(rt.HandleCreateCollectionRequest, "requester", "administrator", "dispatcher"))
	mux.HandleFunc("POST /api/ingest-presealed-sample", rt.AuthMiddleware(rt.HandleIngestPresealedSample, "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "administrator", "dispatcher"))

	// Assignment & Worker
	mux.HandleFunc("POST /api/accept-assignment", rt.AuthMiddleware(rt.HandleAcceptAssignment))
	mux.HandleFunc("POST /api/decline-assignment", rt.AuthMiddleware(rt.HandleDeclineAssignment))
	mux.HandleFunc("POST /api/record-worker-location", rt.AuthMiddleware(rt.HandleRecordWorkerLocation))
	mux.HandleFunc("POST /api/update-assignment-progress", rt.AuthMiddleware(rt.HandleUpdateAssignmentProgress))

	// Custody & Samples
	mux.HandleFunc("POST /api/collect-and-seal-sample", rt.AuthMiddleware(rt.HandleCollectAndSealSample, "collection_professional", "administrator", "dispatcher"))
	mux.HandleFunc("POST /api/initiate-handoff", rt.AuthMiddleware(rt.HandleInitiateHandoff))
	mux.HandleFunc("POST /api/confirm-handoff", rt.AuthMiddleware(rt.HandleConfirmHandoff))
	mux.HandleFunc("POST /api/record-handling-checkpoint", rt.AuthMiddleware(rt.HandleRecordHandlingCheckpoint))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", rt.AuthMiddleware(rt.HandleConfirmLaboratoryReceipt, "laboratory_team", "administrator", "dispatcher"))
	mux.HandleFunc("POST /api/record-laboratory-exception", rt.AuthMiddleware(rt.HandleRecordLaboratoryException, "laboratory_team", "administrator", "dispatcher"))

	// Journey Planning & Disruptions
	mux.HandleFunc("POST /api/edit-active-plan", rt.AuthMiddleware(rt.HandleEditActivePlan, "dispatcher", "administrator"))
	mux.HandleFunc("POST /api/split-journey", rt.AuthMiddleware(rt.HandleSplitJourney, "dispatcher", "administrator"))
	mux.HandleFunc("POST /api/merge-journeys", rt.AuthMiddleware(rt.HandleMergeJourneys, "dispatcher", "administrator"))
	mux.HandleFunc("POST /api/reroute-journey", rt.AuthMiddleware(rt.HandleRerouteJourney, "dispatcher", "administrator"))
	mux.HandleFunc("POST /api/report-disruption", rt.AuthMiddleware(rt.HandleReportDisruption, "dispatcher", "administrator"))
	mux.HandleFunc("POST /api/cancel-journey", rt.AuthMiddleware(rt.HandleCancelJourney, "dispatcher", "administrator"))

	// State, Work & Audit
