// 23. Decline Assignment
func (rt *Router) HandleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	claims := GetClaims(r)
	var req struct {
		AssignmentId   string  `json:"assignmentId"`
		Reason         *string `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		rt.WriteError(w, http.StatusBadRequest, "invalid request body", "BAD_REQUEST")
		return
	}

	if seen, status, resp := checkIdempotency(r.Context(), req.IdempotencyKey); seen {
		rt.WriteJSON(w, status, resp)
		return
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}
	reofferedTo, err := service.DeclineAssignment(r.Context(), claims.UserId, claims.ActiveRole, req.AssignmentId, reasonStr)
	if err != nil {
		rt.WriteError(w, http.StatusBadRequest, err.Error(), "BAD_REQUEST")
		return
	}

	decAtStr := time.Now().UTC().Format(time.RFC3339)
	if req.DeclinedAt != nil && *req.DeclinedAt != "" {
		decAtStr = *req.DeclinedAt
	}

	outData := map[string]any{
		"assignmentId": req.AssignmentId,
		"status":       "pending",
		"declinedBy":   claims.UserId,
		"declinedAt":   decAtStr,
	}
	if reofferedTo != "" {
		outData["reofferedTo"] = reofferedTo
	}

	out := map[string]any{"data": outData}
	saveIdempotency(r.Context(), req.IdempotencyKey, http.StatusCreated, out)
	rt.WriteJSON(w, http.StatusCreated, out)
}

