LEFT JOIN worker_penalties wp ON u.id = wp.worker_id
WHERE u.active = true AND u.available = true AND $1 = ANY(u.roles);
`, targetRole)
	if err != nil {
		return err
	}
	defer rows.Close()

	candidates := make([]EligibleWorker, 0)
	declinedMap := make(map[string]bool)
	for _, d := range declinedIDs {
		declinedMap[d] = true
	}

	for rows.Next() {
		var uid string
		var quals []string
		var certsJSON []byte
		var assignedLoc *string
		var capUnits, decCount, actCount, totCount int

		if err := rows.Scan(&uid, &quals, &certsJSON, &assignedLoc, &capUnits, &decCount, &actCount, &totCount); err != nil {
			return err
		}

		if declinedMap[uid] {
			continue
		}

		// Check location assignment
		if kind == "node" && nodeID != nil && *nodeID != "" {
			if assignedLoc != nil && *assignedLoc != "" && *assignedLoc != *nodeID {
				continue
			}
		}
		if kind == "laboratory" && labID != nil && *labID != "" {
			if assignedLoc != nil && *assignedLoc != "" && *assignedLoc != *labID {
				continue
			}
		}

		// Check qualifications for collection
		if kind == "collection" && st.QualifiedCollectorRequired {
			qualified := false
			for _, q := range quals {
				if q == st.RequiredQualification || q == st.Name || q == "amber_certified" || q == "indigo_certified" || q == "frost_certified" || q == "pulse_certified" {
					if q == st.RequiredQualification || q == st.Name {
						qualified = true
						break
					}
				}
			}
			if !qualified {
				// Check certifications
				var certs []model.Certification
				// ignore err
				for _, c := range certs {
					if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
						qualified = true
						break
					}
				}
			}
			if !qualified {
				continue
			}
		}

		candidates = append(candidates, EligibleWorker{
			UserID:        uid,
			ActiveCount:   actCount,
			DeclineCount:  decCount,
			TotalCount:    totCount,
			CapacityUnits: capUnits,
		})
	}

	if len(candidates) == 0 {
		// No qualified worker available
		if kind == "collection" && st.QualifiedCollectorRequired {
			_ = db.Pool.QueryRow(ctx, `
UPDATE samples
SET status = 'exception',
    exception_details = jsonb_build_object('reason', 'no_qualified_worker_available', 'assignmentId', $1)
WHERE id = $2;
`, assignmentID, sampleID)
			_ = RecordAudit(ctx, "system", "system", "system", "sample.exception", "sample", sampleID, false, map[string]any{
				"reason":       "no_qualified_worker_available",
				"assignmentId": assignmentID,
			})
		}
		return nil
	}

	// Sort candidates by: active_count asc, decline_count asc, total_count asc
	best := candidates[0]
	for _, c := range candidates[1:] {
		if c.ActiveCount < best.ActiveCount ||
			(c.ActiveCount == best.ActiveCount && c.DeclineCount < best.DeclineCount) ||
			(c.ActiveCount == best.ActiveCount && c.DeclineCount == best.DeclineCount && c.TotalCount < best.TotalCount) {
			best = c
		}
	}

	expiresAt := time.Now().UTC().Add(5 * time.Minute)
	_, err = db.Pool.Exec(ctx, `
UPDATE assignments
SET offered_worker_id = $1, offer_expires_at = $2, status = 'offered', updated_at = NOW()
WHERE id = $3;
`, best.UserID, expiresAt, assignmentID)

	_ = RecordAudit(ctx, "system", "system", "system", "assignment.offer", "assignment", assignmentID, true, map[string]any{
		"offeredWorkerId": best.UserID,
		"expiresAt":       expiresAt.Format(time.RFC3339),
	})

	return err
}

func AcceptAssignment(ctx context.Context, actorID, actorRole, assignmentID string) error {
	var offeredWorkerID *string
	var currentStatus string
	var sampleID string

	err := db.Pool.QueryRow(ctx, `
SELECT offered_worker_id, status, sample_id
FROM assignments
WHERE id = $1;
`, assignmentID).Scan(&offeredWorkerID, &currentStatus, &sampleID)
	if err != nil {
		return errors.New("assignment not found")
	}

	if currentStatus == "accepted" {
		return nil
	}

	if offeredWorkerID == nil || *offeredWorkerID != actorID {
		return errors.New("assignment was not offered to you")
	}

	_, err = db.Pool.Exec(ctx, `
UPDATE assignments
SET worker_id = $1, offered_worker_id = NULL, status = 'accepted', updated_at = NOW()
WHERE id = $2;
`, actorID, assignmentID)
	if err != nil {
		return err
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "assignment.accept", "assignment", assignmentID, true, map[string]any{
		"workerId": actorID,
		"sampleId": sampleID,
	})

	return nil
}

func DeclineAssignment(ctx context.Context, actorID, actorRole, assignmentID, reason string) (string, error) {
	var offeredWorkerID *string
	var sampleID string

	err := db.Pool.QueryRow(ctx, `
SELECT offered_worker_id, sample_id
FROM assignments
WHERE id = $1;
`, assignmentID).Scan(&offeredWorkerID, &sampleID)
	if err != nil {
		return "", errors.New("assignment not found")
	}

	if offeredWorkerID == nil || *offeredWorkerID != actorID {
		return "", errors.New("assignment was not offered to you")
	}

	// Update assignment
	_, err = db.Pool.Exec(ctx, `
UPDATE assignments
SET offered_worker_id = NULL, offer_expires_at = NULL, status = 'pending',
    declined_worker_ids = array_append(declined_worker_ids, $1::uuid), updated_at = NOW()
WHERE id = $2;
`, actorID, assignmentID)
	if err != nil {
		return "", err
	}

	// Update penalty
	_, _ = db.Pool.Exec(ctx, `
INSERT INTO worker_penalties (worker_id, decline_count, last_declined_at)
VALUES ($1, 1, NOW())
ON CONFLICT (worker_id) DO UPDATE
SET decline_count = worker_penalties.decline_count + 1, last_declined_at = NOW();
`, actorID)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "assignment.decline", "assignment", assignmentID, true, map[string]any{
		"declinedBy": actorID,
		"reason":     reason,
	})

	// Re-offer
	_ = FindAndOfferWorker(ctx, assignmentID)

	var reofferedTo *string
	_ = db.Pool.QueryRow(ctx, "SELECT offered_worker_id FROM assignments WHERE id = $1", assignmentID).Scan(&reofferedTo)

	reofferedStr := ""
	if reofferedTo != nil {
		reofferedStr = *reofferedTo
	}

	return reofferedStr, nil
}

