package service

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"time"

	"backend/internal/db"
	"backend/internal/model"

	"github.com/golang-jwt/jwt/v5"
	"github.com/google/uuid"
	"golang.org/x/crypto/bcrypt"
)

var JWTSecret = []byte("arena-lab-sample-secret-key-change-in-prod")

type Claims struct {
	UserId     string   `json:"userId"`
	Username   string   `json:"username"`
	Roles      []string `json:"roles"`
	ActiveRole string   `json:"activeRole"`
	jwt.RegisteredClaims
}

func EnsureDefaultAdmin(ctx context.Context, username, password string) error {
	var count int
	err := db.Pool.QueryRow(ctx, "SELECT COUNT(*) FROM users").Scan(&count)
	if err != nil {
		return err
	}
	if count > 0 {
		return nil
	}

	if username == "" {
		username = os.Getenv("ADMIN_USERNAME")
	}
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = os.Getenv("ADMIN_PASSWORD")
	}
	if password == "" {
		password = "Admin123!"
	}

	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return err
	}

	adminID := uuid.New().String()
	roles := []string{"administrator", "dispatcher"}
	fullName := "System Administrator"

	_, err = db.Pool.Exec(ctx, `
INSERT INTO users (id, username, password_hash, full_name, roles, active_role, active)
VALUES ($1, $2, $3, $4, $5, 'administrator', true)
ON CONFLICT (username) DO NOTHING;
`, adminID, username, string(hash), fullName, roles)

	if err != nil {
		return fmt.Errorf("failed to create initial admin: %w", err)
	}

	_ = RecordAudit(ctx, adminID, "administrator", "administrator", "user.create", "user", adminID, true, map[string]any{
		"username": username,
		"roles":    roles,
	})

	return nil
}

func EnsureAdminUser(ctx context.Context) error {
	return EnsureDefaultAdmin(ctx, "", "")
}

func GenerateToken(u *model.User) (string, error) {
	claims := Claims{
		UserId:     u.UserId,
		Username:   u.Username,
		Roles:      u.Roles,
		ActiveRole: u.ActiveRole,
		RegisteredClaims: jwt.RegisteredClaims{
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(24 * time.Hour)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}
	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	return token.SignedString(JWTSecret)
}

func ValidateToken(tokenStr string) (*Claims, error) {
	token, err := jwt.ParseWithClaims(tokenStr, &Claims{}, func(token *jwt.Token) (interface{}, error) {
		if _, ok := token.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, fmt.Errorf("unexpected signing method")
		}
		return JWTSecret, nil
	})
	if err != nil {
		return nil, err
	}
	if claims, ok := token.Claims.(*Claims); ok && token.Valid {
		return claims, nil
	}
	return nil, errors.New("invalid token")
}

func AuthenticateUser(ctx context.Context, username, password string) (string, *model.User, error) {
	var u model.User
	var certsJSON []byte
	var assignedLoc *string
	var lat, lng *float64
	var recAt *time.Time

	err := db.Pool.QueryRow(ctx, `
SELECT id, username, password_hash, email, full_name, phone, roles, active_role, qualifications, certifications, active, assigned_location_id, available, capacity_units, latitude, longitude, location_recorded_at, created_at
FROM users
WHERE username = $1;
`, username).Scan(
		&u.UserId, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&u.Roles, &u.ActiveRole, &u.Qualifications, &certsJSON, &u.Active,
		&assignedLoc, &u.Available, &u.CapacityUnits, &lat, &lng, &recAt, &u.CreatedAt,
	)
	if err != nil {
		return "", nil, errors.New("invalid credentials")
	}

	if !u.Active {
		return "", nil, errors.New("user is inactive")
	}

	if err := bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(password)); err != nil {
		return "", nil, errors.New("invalid credentials")
	}

	u.AssignedLocationId = assignedLoc
	u.Latitude = lat
	u.Longitude = lng
	u.LocationRecordedAt = recAt
	if len(certsJSON) > 0 {
		_ = json.Unmarshal(certsJSON, &u.Certifications)
	}
	if u.Certifications == nil {
		u.Certifications = []model.Certification{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}

	token, err := GenerateToken(&u)
	if err != nil {
		return "", nil, err
	}

	_ = RecordAudit(ctx, u.UserId, u.ActiveRole, u.ActiveRole, "user.login", "user", u.UserId, true, map[string]any{
		"username": username,
	})

	return token, &u, nil
}

func SelectActiveRole(ctx context.Context, userID, newRole string) (string, []string, error) {
	var roles []string
	var activeRole string
	err := db.Pool.QueryRow(ctx, "SELECT roles, active_role FROM users WHERE id = $1", userID).Scan(&roles, &activeRole)
	if err != nil {
		return "", nil, errors.New("user not found")
	}

	hasRole := false
	for _, r := range roles {
		if r == newRole {
			hasRole = true
			break
		}
	}
	if !hasRole {
		return "", nil, errors.New("user does not have this role")
	}

	_, err = db.Pool.Exec(ctx, "UPDATE users SET active_role = $1 WHERE id = $2", newRole, userID)
	if err != nil {
		return "", nil, err
	}

	_ = RecordAudit(ctx, userID, newRole, newRole, "user.switch_role", "user", userID, true, map[string]any{
		"previousRole": activeRole,
		"newRole":      newRole,
	})

	return newRole, roles, nil
}

func GetUserByID(ctx context.Context, userID string) (*model.User, error) {
	var u model.User
	var certsJSON []byte
	var assignedLoc *string
	var lat, lng *float64
	var recAt *time.Time

	err := db.Pool.QueryRow(ctx, `
SELECT id, username, password_hash, email, full_name, phone, roles, active_role, qualifications, certifications, active, assigned_location_id, available, capacity_units, latitude, longitude, location_recorded_at, created_at
FROM users
WHERE id = $1;
`, userID).Scan(
		&u.UserId, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&u.Roles, &u.ActiveRole, &u.Qualifications, &certsJSON, &u.Active,
		&assignedLoc, &u.Available, &u.CapacityUnits, &lat, &lng, &recAt, &u.CreatedAt,
	)
	if err != nil {
		return nil, errors.New("user not found")
	}

	u.AssignedLocationId = assignedLoc
	u.Latitude = lat
	u.Longitude = lng
	u.LocationRecordedAt = recAt
	if len(certsJSON) > 0 {
		_ = json.Unmarshal(certsJSON, &u.Certifications)
	}
	if u.Certifications == nil {
		u.Certifications = []model.Certification{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}

	return &u, nil
}

