    UNIQUE(laboratory_id, sample_type_id)
);

CREATE TABLE IF NOT EXISTS connections (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    from_location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
    to_location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
    travel_minutes INT NOT NULL DEFAULT 30,
    cost_units DOUBLE PRECISION NOT NULL DEFAULT 10.0,
    cooled BOOLEAN NOT NULL DEFAULT FALSE,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    capacity_units INT NOT NULL DEFAULT 50,
    reserved_units INT NOT NULL DEFAULT 0,
    cooled_capacity_units INT NOT NULL DEFAULT 25,
    cooled_reserved_units INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_connections_from_to ON connections(from_location_id, to_location_id);

CREATE TABLE IF NOT EXISTS serviceability_snapshots (
    version INT PRIMARY KEY,
    status TEXT NOT NULL DEFAULT 'complete',
    computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    network_revision INT NOT NULL DEFAULT 1,
    regions JSONB NOT NULL DEFAULT '[]',
    active_collection_point_count INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS requests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    requester_id UUID NOT NULL REFERENCES users(id),
    sample_id UUID NOT NULL,
    origin_lat DOUBLE PRECISION NOT NULL,
    origin_lng DOUBLE PRECISION NOT NULL,
    origin_type TEXT NOT NULL DEFAULT 'home',
    origin_node_id UUID,
    requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    delivery_deadline TIMESTAMPTZ NOT NULL,
    earliest_collection_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    latest_collection_at TIMESTAMPTZ NOT NULL,
    sample_type_id UUID NOT NULL REFERENCES sample_types(id),
    container_type TEXT NOT NULL,
    temperature_min_c DOUBLE PRECISION NOT NULL,
    temperature_max_c DOUBLE PRECISION NOT NULL,
    incompatible_sample_types UUID[] NOT NULL DEFAULT '{}',
    serviceability TEXT NOT NULL DEFAULT 'serviceable',
    serviceability_reason TEXT NOT NULL DEFAULT 'serviceable',
    journey_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_requests_requester ON requests(requester_id);

CREATE TABLE IF NOT EXISTS samples (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    request_id UUID NOT NULL REFERENCES requests(id) ON DELETE CASCADE,
    requester_id UUID NOT NULL REFERENCES users(id),
    sample_type_id UUID NOT NULL REFERENCES sample_types(id),
    status TEXT NOT NULL DEFAULT 'requested',
    sealed BOOLEAN NOT NULL DEFAULT FALSE,
    sealed_at TIMESTAMPTZ,
    current_holder_id UUID REFERENCES users(id),
    active_journey_id UUID,
    target_laboratory_id UUID REFERENCES locations(id),
    received_laboratory_id UUID REFERENCES locations(id),
    latest_lat DOUBLE PRECISION,
    latest_lng DOUBLE PRECISION,
    location_recorded_at TIMESTAMPTZ,
    exception_details JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_samples_status ON samples(status);
CREATE INDEX IF NOT EXISTS idx_samples_requester ON samples(requester_id);
CREATE INDEX IF NOT EXISTS idx_samples_holder ON samples(current_holder_id);

CREATE TABLE IF NOT EXISTS journeys (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    parent_journey_id UUID REFERENCES journeys(id),
    plan_version INT NOT NULL DEFAULT 1,
    route_mode TEXT NOT NULL DEFAULT 'direct',
    status TEXT NOT NULL DEFAULT 'active',
    estimated_delivery_at TIMESTAMPTZ,
    total_cost_units DOUBLE PRECISION NOT NULL DEFAULT 0.0,
    capacity_used INT NOT NULL DEFAULT 1,
    capacity_available INT NOT NULL DEFAULT 10,
    replan_status TEXT,
    valid BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS journey_samples (
    journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    PRIMARY KEY(journey_id, sample_id)
);

CREATE TABLE IF NOT EXISTS journey_stops (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
    location_id UUID NOT NULL,
    stop_type TEXT NOT NULL,
    sequence INT NOT NULL,
    estimated_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ,
    dwell_minutes INT NOT NULL DEFAULT 10,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_journey_stops_journey ON journey_stops(journey_id, sequence);

CREATE TABLE IF NOT EXISTS assignments (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    sequence INT NOT NULL DEFAULT 1,
    status TEXT NOT NULL DEFAULT 'offered',
    from_location_id UUID,
    to_location_id UUID,
    node_id UUID,
    laboratory_id UUID,
    expected_sample_type_id UUID,
    worker_id UUID REFERENCES users(id),
    offered_worker_id UUID REFERENCES users(id),
    offer_expires_at TIMESTAMPTZ,
    declined_worker_ids UUID[] NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_assignments_worker ON assignments(worker_id);
CREATE INDEX IF NOT EXISTS idx_assignments_offered ON assignments(offered_worker_id);
CREATE INDEX IF NOT EXISTS idx_assignments_sample ON assignments(sample_id);

CREATE TABLE IF NOT EXISTS capacity_reservations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    resource_type TEXT NOT NULL,
    resource_id UUID NOT NULL,
    units INT NOT NULL DEFAULT 1,
    cooled BOOLEAN NOT NULL DEFAULT FALSE,
    released BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS handoffs (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
    from_assignment_id UUID REFERENCES assignments(id),
    to_assignment_id UUID REFERENCES assignments(id),
    sender_id UUID NOT NULL REFERENCES users(id),
    receiver_id UUID NOT NULL REFERENCES users(id),
    current_holder_id UUID NOT NULL REFERENCES users(id),
    status TEXT NOT NULL DEFAULT 'pending',
    sender_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
    receiver_confirmed BOOLEAN NOT NULL DEFAULT FALSE,
    sender_confirmed_at TIMESTAMPTZ,
    receiver_confirmed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_handoffs_sample ON handoffs(sample_id);

CREATE TABLE IF NOT EXISTS worker_location_logs (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    assignment_id UUID NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,
    worker_id UUID NOT NULL REFERENCES users(id),
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    sequence INT NOT NULL DEFAULT 1,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS audit_entries (
    id BIGSERIAL PRIMARY KEY,
    audit_id UUID NOT NULL DEFAULT uuid_generate_v4(),
    actor_id UUID NOT NULL,
    role TEXT NOT NULL,
    actor_role TEXT NOT NULL,
    action TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id TEXT NOT NULL,
    success BOOLEAN NOT NULL DEFAULT TRUE,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    details JSONB NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_audit_occurred ON audit_entries(occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_entries(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_entries(actor_id);

CREATE TABLE IF NOT EXISTS realtime_events (
    id BIGSERIAL PRIMARY KEY,
    type TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_realtime_id ON realtime_events(id);

CREATE TABLE IF NOT EXISTS worker_penalties (
    worker_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    decline_count INT NOT NULL DEFAULT 0,
    last_declined_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS idempotency_keys (
    key TEXT PRIMARY KEY,
    response_status INT NOT NULL,
    response_body JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
`
	if _, err := pool.Exec(ctx, schema); err != nil {
		return fmt.Errorf("failed to run migrations: %w", err)
	}

	if err := SeedInitialData(ctx, pool); err != nil {
		return fmt.Errorf("failed to seed initial data: %w", err)
	}

	return nil
}

func SeedInitialData(ctx context.Context, pool *pgxpool.Pool) error {
	var count int
	err := pool.QueryRow(ctx, "SELECT COUNT(*) FROM sample_types").Scan(&count)
	if err != nil {
		return err
	}
	if count > 0 {
		return nil
	}

	// 1. Insert Default Sample Types
	amberID := "11111111-1111-1111-1111-111111111111"
	indigoID := "22222222-2222-2222-2222-222222222222"
	frostID := "33333333-3333-3333-3333-333333333333"
	pulseID := "44444444-4444-4444-4444-444444444444"

	_, err = pool.Exec(ctx, `
INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
VALUES
  ($1, 'Amber', true, 'amber_certified', 'standard_box', 15.0, 25.0, ARRAY[$2::uuid], false, true),
  ($2, 'Indigo', true, 'indigo_certified', 'standard_box', 15.0, 25.0, ARRAY[$1::uuid], false, true),
  ($3, 'Frost', true, 'frost_certified', 'cryo_cooler', -20.0, 4.0, '{}', true, true),
  ($4, 'Pulse', true, 'pulse_certified', 'rapid_secure', 15.0, 25.0, '{}', false, false)
ON CONFLICT (name) DO NOTHING;
`, amberID, indigoID, frostID, pulseID)
	if err != nil {
		return fmt.Errorf("failed to insert sample types: %w", err)
	}

	// 2. Insert Default Locations in Bangalore
	loc1 := "aaaaaaaa-1111-1111-1111-111111111111" // Indiranagar Collection Centre
	loc2 := "bbbbbbbb-2222-2222-2222-222222222222" // Koramangala Hub
	loc3 := "cccccccc-3333-3333-3333-333333333333" // Malleshwaram Collection Point
	loc4 := "dddddddd-4444-4444-4444-444444444444" // Central Diagnostics Lab
	loc5 := "eeeeeeee-5555-5555-5555-555555555555" // Whitefield Diagnostics Hub & Lab

	_, err = pool.Exec(ctx, `
INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, is_collection_point, is_transfer_point, is_hub, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
VALUES
  ($1, 'Indiranagar Collection Centre', 12.9784, 77.6408, 5.0, 15, true, true, true, false, false, 100, 0, 50, 0),
  ($2, 'Koramangala Hub', 12.9352, 77.6245, 5.0, 20, true, true, true, true, false, 200, 0, 100, 0),
  ($3, 'Malleshwaram Collection Point', 13.0031, 77.5643, 5.0, 15, true, true, true, false, false, 80, 0, 40, 0),
  ($4, 'Central Diagnostics Lab', 12.9716, 77.5946, 5.0, 30, true, false, true, true, true, 500, 0, 250, 0),
  ($5, 'Whitefield Diagnostics Hub & Lab', 12.9698, 77.7499, 5.0, 25, true, true, true, true, true, 300, 0, 150, 0)
ON CONFLICT (id) DO NOTHING;
`, loc1, loc2, loc3, loc4, loc5)
	if err != nil {
		return fmt.Errorf("failed to insert locations: %w", err)
	}

	// 3. Insert Laboratory Acceptance
	for _, labID := range []string{loc4, loc5} {
		for _, stID := range []string{amberID, indigoID, frostID, pulseID} {
			_, err = pool.Exec(ctx, `
INSERT INTO laboratory_acceptance (laboratory_id, sample_type_id, accepts)
VALUES ($1, $2, true)
ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts = true;
`, labID, stID)
			if err != nil {
				return fmt.Errorf("failed to insert lab acceptance: %w", err)
			}
		}
	}

	// 4. Insert Connections between nodes (both directions)
	conns := []struct {
		from, to string
		mins     int
		cost     float64
		cooled   bool
	}{
		{loc1, loc4, 25, 15.0, true},
		{loc4, loc1, 25, 15.0, true},
		{loc2, loc4, 20, 12.0, true},
		{loc4, loc2, 20, 12.0, true},
		{loc3, loc4, 22, 14.0, true},
		{loc4, loc3, 22, 14.0, true},
		{loc1, loc2, 18, 10.0, true},
		{loc2, loc1, 18, 10.0, true},
		{loc2, loc5, 35, 25.0, true},
		{loc5, loc2, 35, 25.0, true},
		{loc1, loc5, 30, 20.0, true},
		{loc5, loc1, 30, 20.0, true},
		{loc3, loc2, 30, 18.0, true},
		{loc2, loc3, 30, 18.0, true},
	}

	for _, c := range conns {
		_, err = pool.Exec(ctx, `
INSERT INTO connections (from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
VALUES ($1, $2, $3, $4, $5, true, 50, 0, 25, 0)
`, c.from, c.to, c.mins, c.cost, c.cooled)
		if err != nil {
			return fmt.Errorf("failed to insert connection: %w", err)
		}
	}

	// 5. Compute Initial Serviceability Snapshot
	_, err = pool.Exec(ctx, `
INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
VALUES (
  1,
  'complete',
  NOW(),
  1,
  jsonb_build_array(
    jsonb_build_object('locationId', '`+loc1+`', 'name', 'Indiranagar Collection Centre', 'latitude', 12.9784, 'longitude', 77.6408, 'coverageKm', 5.0),
    jsonb_build_object('locationId', '`+loc2+`', 'name', 'Koramangala Hub', 'latitude', 12.9352, 'longitude', 77.6245, 'coverageKm', 5.0),
    jsonb_build_object('locationId', '`+loc3+`', 'name', 'Malleshwaram Collection Point', 'latitude', 13.0031, 'longitude', 77.5643, 'coverageKm', 5.0),
    jsonb_build_object('locationId', '`+loc5+`', 'name', 'Whitefield Diagnostics Hub & Lab', 'latitude', 12.9698, 'longitude', 77.7499, 'coverageKm', 5.0)
  ),
  4
)
ON CONFLICT (version) DO NOTHING;
`)
	if err != nil {
		return fmt.Errorf("failed to insert serviceability snapshot: %w", err)
	}

	return nil
}

