package main

import (
	"context"
	"log"
	"time"

	"backend/internal/db"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	log.Println("Resetting database...")
	pool, err := db.InitDB(ctx)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer pool.Close()

	// Drop existing tables
	dropQuery := `
DROP TABLE IF EXISTS worker_penalties CASCADE;
DROP TABLE IF EXISTS worker_location_logs CASCADE;
DROP TABLE IF EXISTS capacity_reservations CASCADE;
DROP TABLE IF EXISTS handoffs CASCADE;
DROP TABLE IF EXISTS assignments CASCADE;
DROP TABLE IF EXISTS journey_stops CASCADE;
DROP TABLE IF EXISTS journey_samples CASCADE;
DROP TABLE IF EXISTS journeys CASCADE;
DROP TABLE IF EXISTS samples CASCADE;
DROP TABLE IF EXISTS requests CASCADE;
DROP TABLE IF EXISTS connections CASCADE;
DROP TABLE IF EXISTS laboratory_acceptance CASCADE;
DROP TABLE IF EXISTS locations CASCADE;
DROP TABLE IF EXISTS sample_types CASCADE;
DROP TABLE IF EXISTS serviceability_snapshots CASCADE;
DROP TABLE IF EXISTS audit_entries CASCADE;
DROP TABLE IF EXISTS realtime_events CASCADE;
DROP TABLE IF EXISTS idempotency_keys CASCADE;
DROP TABLE IF EXISTS users CASCADE;
`
	if _, err := pool.Exec(ctx, dropQuery); err != nil {
		log.Fatalf("Failed to drop tables: %v", err)
	}

	// Materialize schema and seed
	if err := db.MigrateAndMaterialize(ctx, pool); err != nil {
		log.Fatalf("Failed to materialize schema: %v", err)
	}

	log.Println("Database reset completed successfully.")
}

