package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"backend/internal/db"
	"backend/internal/handler"
	"backend/internal/service"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	log.Println("Initializing databases...")
	if err := db.InitDBs(ctx); err != nil {
		log.Fatalf("Failed to initialize databases: %v", err)
	}

	adminUser := os.Getenv("ADMIN_USERNAME")
	if adminUser == "" {
		adminUser = "admin"
	}
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminPass == "" {
		adminPass = "AdminPassword123!"
	}

	log.Printf("Ensuring initial admin user '%s'...", adminUser)
	if err := service.EnsureDefaultAdmin(context.Background(), adminUser, adminPass); err != nil {
		log.Fatalf("Failed to ensure default admin: %v", err)
	}

	_ = service.RecomputeServiceabilitySnapshot(context.Background())

	router := handler.NewRouter()
	mux := http.NewServeMux()
	router.RegisterRoutes(mux)

	// Serve PMTiles map asset
	mux.HandleFunc("/tiles/bangalore.pmtiles", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Range, Origin, Content-Type, Accept")
		w.Header().Set("Access-Control-Expose-Headers", "Content-Range, Content-Length, Accept-Ranges")
		http.ServeFile(w, r, "/opt/arena/map-assets/bangalore.pmtiles")
	})

	// Serve static frontend files if directory exists
	frontendDist := "/workspace/frontend/dist"
	fileServer := http.FileServer(http.Dir(frontendDist))
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if stringsHasPrefix(r.URL.Path, "/api") || stringsHasPrefix(r.URL.Path, "/ready") || stringsHasPrefix(r.URL.Path, "/tiles") {
			return
		}
		// If requesting a specific file that exists, serve it
		path := frontendDist + r.URL.Path
		if fi, err := os.Stat(path); err == nil && !fi.IsDir() {
			fileServer.ServeHTTP(w, r)
			return
		}
		// Otherwise serve index.html for SPA client-side routing
		http.ServeFile(w, r, frontendDist+"/index.html")
	})

	// CORS wrapper
	corsHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With, Range, Idempotency-Key")
		w.Header().Set("Access-Control-Expose-Headers", "Content-Range, Content-Length, Accept-Ranges")

		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}

		mux.ServeHTTP(w, r)
	})

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := &http.Server{
		Addr:    ":" + port,
		Handler: corsHandler,
	}

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	go func() {
		log.Printf("Server listening on http://127.0.0.1:%s", port)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server error: %v", err)
		}
	}()

	<-stop
	log.Println("Shutting down server gracefully...")

	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer shutdownCancel()

	if err := server.Shutdown(shutdownCtx); err != nil {
		log.Printf("Server shutdown error: %v", err)
	}
	db.CloseDBs()
	log.Println("Server stopped.")
}

func stringsHasPrefix(s, prefix string) bool {
	return len(s) >= len(prefix) && s[:len(prefix)] == prefix
}

