import React, { useEffect, useState } from 'react';
import { SampleState, SampleLifecycle } from '../types';
import { api } from '../api/client';
import { StatusTimeline } from './StatusTimeline';
import {
  X,
  AlertTriangle,
  Clock,
  MapPin,
  User,
  ShieldCheck,
  Thermometer,
  Package,
  Activity,
  Calendar,
} from 'lucide-react';

interface SampleDetailModalProps {
  sampleId: string;
  onClose: () => void;
}

export const SampleDetailModal: React.FC<SampleDetailModalProps> = ({ sampleId, onClose }) => {
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchLifecycle = async () => {
      try {
        setIsLoading(true);
        const data = await api.readSampleLifecycle(sampleId);
        setLifecycle(data);
      } catch (err: any) {
        setError(err.message || 'Failed to load sample details');
      } finally {
        setIsLoading(false);
      }
    };
    if (sampleId) {
      fetchLifecycle();
    }
  }, [sampleId]);

  if (!sampleId) return null;

  const sample = lifecycle?.sample;

  // Calculate route progress (placeholder or based on completed legs)
  const getProgressPercentage = () => {
    if (!sample) return 0;
    if (sample.status === 'delivered_to_laboratory' || sample.status === 'received_at_lab' || sample.status === 'completed') return 100;
    if (sample.status === 'in_transit' || sample.status === 'transferring') return 60;
    if (sample.status === 'collected_and_sealed' || sample.status === 'picked_up') return 30;
    if (sample.status === 'assigned' || sample.status === 'scheduled') return 15;
    return 5;
  };

  const progress = getProgressPercentage();

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] flex flex-col overflow-hidden border border-slate-200 animate-in fade-in zoom-in-95 duration-200">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-slate-50">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-xl bg-teal-600 text-white flex items-center justify-center font-bold text-lg shadow-sm">
              <Package className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h3 className="text-lg font-bold text-slate-900" data-testid="sample-modal-title">
                  Sample {sampleId.slice(0, 13)}
                </h3>
                {sample?.sample_type_name && (
                  <span className="px-2 py-0.5 rounded text-xs font-semibold bg-teal-100 text-teal-800 border border-teal-200">
                    {sample.sample_type_name}
                  </span>
                )}
              </div>
              <p className="text-xs text-slate-500">
                Created: {sample?.created_at ? new Date(sample.created_at).toLocaleString() : 'N/A'}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            aria-label="Close"
            className="text-slate-400 hover:text-slate-600 p-1.5 rounded-lg hover:bg-slate-200/60 transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {isLoading ? (
            <div className="py-12 text-center text-slate-500">Loading sample lifecycle...</div>
          ) : error ? (
            <div className="p-4 bg-red-50 text-red-700 rounded-lg text-sm border border-red-200">
              {error}
            </div>
          ) : sample ? (
            <>
              {/* Exception Warning Banner */}
              {sample.has_exception && (
                <div
                  data-testid="sample-exception-banner"
                  className="p-4 bg-red-50 border-l-4 border-red-600 rounded-r-lg flex items-start space-x-3"
                >
                  <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                  <div>
                    <h4 className="text-sm font-bold text-red-900">Exception Flagged on Sample</h4>
                    <p className="text-xs text-red-800 mt-0.5">
                      {sample.exception_reason || 'Sample requires operational attention or recheck.'}
                    </p>
                  </div>
                </div>
              )}

              {/* Key Tracking Cards */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Current Custodian */}
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-1">
                  <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center">
                    <User className="w-3.5 h-3.5 mr-1 text-slate-400" /> Current Custodian
                  </div>
                  <div className="font-bold text-slate-900 text-sm" data-testid="sample-custodian-name">
                    {sample.current_holder_name || 'Network Node / Pending'}
                  </div>
                  <div className="text-xs text-slate-500 capitalize">
                    {sample.current_holder_role ? sample.current_holder_role.replace(/_/g, ' ') : 'Facility Hold'}
                  </div>
                </div>

                {/* Latest Location & Freshness */}
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-1">
                  <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center justify-between">
                    <span className="flex items-center">
                      <MapPin className="w-3.5 h-3.5 mr-1 text-slate-400" /> Latest Location
                    </span>
                    {/* Location Freshness Badge */}
                    <span
                      data-testid="sample-freshness-badge"
                      className={`text-[10px] font-bold px-1.5 py-0.5 rounded uppercase tracking-wider ${
                        sample.is_location_stale
                          ? 'bg-amber-100 text-amber-800 border border-amber-300'
                          : 'bg-emerald-100 text-emerald-800 border border-emerald-300'
                      }`}
                    >
                      {sample.is_location_stale ? 'Stale Location' : 'Fresh'}
                    </span>
                  </div>
                  <div className="font-bold text-slate-900 text-sm truncate" data-testid="sample-location-text">
                    {sample.current_location_name || sample.latest_location_address || (sample.latest_latitude ? `${sample.latest_latitude.toFixed(4)}, ${sample.latest_longitude?.toFixed(4)}` : 'Origin Location')}
                  </div>
                  <div className="text-xs text-slate-500 flex items-center">
                    <Clock className="w-3 h-3 mr-1 text-slate-400" />
                    Updated: {sample.last_location_update_at ? new Date(sample.last_location_update_at).toLocaleTimeString() : 'Recently'}
                  </div>
                </div>

                {/* Status & Deadline */}
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-1">
                  <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center">
                    <Activity className="w-3.5 h-3.5 mr-1 text-slate-400" /> Status & Deadline
                  </div>
                  <div className="font-bold text-slate-900 text-sm capitalize" data-testid="sample-status-text">
                    {sample.status.replace(/_/g, ' ')}
                  </div>
                  <div className="text-xs text-slate-500">
                    Deadline: {sample.delivery_deadline ? new Date(sample.delivery_deadline).toLocaleTimeString() : 'N/A'}
                  </div>
                </div>
              </div>

              {/* Route Progress Bar */}
              <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="font-semibold text-slate-700">Journey Progress</span>
                  <span className="font-bold text-teal-700" data-testid="sample-progress-percent">
                    {progress}%
                  </span>
                </div>
                <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                  <div
                    className="bg-teal-600 h-2.5 rounded-full transition-all duration-500"
                    style={{ width: `${progress}%` }}
                  />
                </div>
              </div>

              {/* Sample Details Grid */}
              <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
                <div>
                  <span className="text-slate-500 block">Is Sealed</span>
                  <span className="font-semibold text-slate-900">
                    {sample.is_sealed ? `Yes (Tag: ${sample.seal_tag || 'Verified'})` : 'No'}
                  </span>
                </div>
                <div>
                  <span className="text-slate-500 block">Temperature Req</span>
                  <span className="font-semibold text-slate-900">
                    {sample.requires_cooling ? 'Cooled Storage (2-8°C)' : 'Ambient (15-25°C)'}
                  </span>
                </div>
                <div>
                  <span className="text-slate-500 block">Origin</span>
                  <span className="font-semibold text-slate-900 truncate block">
                    {sample.origin_name || sample.origin_type || 'Patient Home'}
                  </span>
                </div>
                <div>
                  <span className="text-slate-500 block">Destination Lab</span>
                  <span className="font-semibold text-slate-900 truncate block">
                    {sample.destination_lab_name || 'Central Lab'}
                  </span>
                </div>
              </div>

              {/* Ordered Status Timeline */}
              <div className="space-y-3 pt-2">
                <h4 className="text-sm font-bold text-slate-900 flex items-center">
                  <Calendar className="w-4 h-4 mr-2 text-teal-600" />
                  Ordered Status Timeline & History
                </h4>
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                  <StatusTimeline events={lifecycle.events || []} />
                </div>
              </div>
            </>
          ) : null}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 bg-slate-100 border-t border-slate-200 flex justify-end">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 rounded-lg text-sm font-medium transition"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

