  Clock,
  MapPin,
  Package,
  Calendar,
  Layers,
} from 'lucide-react';

interface RequesterViewProps {
  initialTab?: 'samples' | 'serviceability' | 'create_request';
}

export const RequesterView: React.FC<RequesterViewProps> = ({ initialTab = 'samples' }) => {
  const [activeTab, setActiveTab] = useState<'samples' | 'serviceability' | 'create_request'>(initialTab);
  const [sampleTypes, setSampleTypes] = useState<SampleType[]>([]);
  const [samples, setSamples] = useState<SampleState[]>([]);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // Serviceability check state
  const [checkForm, setCheckForm] = useState({
    originLatitude: 12.9716,
    originLongitude: 77.5946,
    sampleTypeId: '',
    collectionWindowEarliest: new Date(Date.now() + 3600000).toISOString().slice(0, 16),
    collectionWindowLatest: new Date(Date.now() + 7200000).toISOString().slice(0, 16),
    deliveryDeadline: new Date(Date.now() + 18000000).toISOString().slice(0, 16),
  });
  const [serviceabilityResult, setServiceabilityResult] = useState<any>(null);

  // Create Request state
  const [requestForm, setRequestForm] = useState({
    originType: 'home',
    originLatitude: 12.9716,
    originLongitude: 77.5946,
    originAddress: '123 MG Road, Bangalore',
    sampleTypeId: '',
    collectionWindowEarliest: new Date(Date.now() + 3600000).toISOString().slice(0, 16),
    collectionWindowLatest: new Date(Date.now() + 7200000).toISOString().slice(0, 16),
    deliveryDeadline: new Date(Date.now() + 18000000).toISOString().slice(0, 16),
    notes: 'Please ring bell',
  });
  const [requestFormError, setRequestFormError] = useState<string | null>(null);

  const fetchSampleTypesAndSamples = async () => {
    try {
      const snap = await api.readServiceabilitySnapshot();
      if (snap && snap.sample_types) {
        setSampleTypes(snap.sample_types);
        if (snap.sample_types.length > 0 && !checkForm.sampleTypeId) {
          setCheckForm((f) => ({ ...f, sampleTypeId: snap.sample_types[0].id }));
          setRequestForm((f) => ({ ...f, sampleTypeId: snap.sample_types[0].id }));
        }
      }

      // Fetch my requests/samples
      const bootstrap = await api.getUIBootstrap();
      if (bootstrap && bootstrap.requesterSamples) {
        setSamples(bootstrap.requesterSamples);
      }
    } catch (err: any) {
      console.error('Error loading requester data:', err);
    }
  };

  useEffect(() => {
    fetchSampleTypesAndSamples();
  }, []);

  const handleCheckServiceability = async (e: React.FormEvent) => {
    e.preventDefault();
    setServiceabilityResult(null);
    setLoading(true);
    try {
      const res = await api.checkServiceability({
        originLatitude: Number(checkForm.originLatitude),
        originLongitude: Number(checkForm.originLongitude),
        sampleTypeId: checkForm.sampleTypeId,
        collectionWindowEarliest: new Date(checkForm.collectionWindowEarliest).toISOString(),
        collectionWindowLatest: new Date(checkForm.collectionWindowLatest).toISOString(),
        deliveryDeadline: new Date(checkForm.deliveryDeadline).toISOString(),
      });
      setServiceabilityResult(res);
    } catch (err: any) {
      setServiceabilityResult({
        serviceable: false,
        reasons: [err.message || 'Serviceability check failed'],
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setRequestFormError(null);
    setFeedback(null);

    // Validation
    const earliest = new Date(requestForm.collectionWindowEarliest);
    const latest = new Date(requestForm.collectionWindowLatest);
    const deadline = new Date(requestForm.deliveryDeadline);

    if (earliest >= latest) {
      setRequestFormError('Collection window earliest time must be before latest time.');
      return;
    }
    if (latest >= deadline) {
      setRequestFormError('Delivery deadline must be strictly after collection window latest time.');
      return;
    }
    if (!requestForm.sampleTypeId) {
      setRequestFormError('Please select a valid sample type.');
      return;
    }

    setLoading(true);
    try {
      const res = await api.createCollectionRequest({
        originType: requestForm.originType,
        originLatitude: Number(requestForm.originLatitude),
        originLongitude: Number(requestForm.originLongitude),
        originAddress: requestForm.originAddress,
        sampleTypeId: requestForm.sampleTypeId,
        collectionWindowEarliest: earliest.toISOString(),
        collectionWindowLatest: latest.toISOString(),
        deliveryDeadline: deadline.toISOString(),
        notes: requestForm.notes,
      });

      setFeedback({
        type: 'success',
        message: `Collection request created successfully! Sample ID: ${res.sampleId || 'Generated'}`,
      });
      fetchSampleTypesAndSamples();
      setActiveTab('samples');
    } catch (err: any) {
      setRequestFormError(err.message || 'Failed to create collection request.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      {/* Subnav for Requester */}
      <div className="flex border-b border-slate-200">
        <button
          onClick={() => setActiveTab('samples')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeTab === 'samples'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Package className="w-4 h-4" />
          <span>My Samples & Requests ({samples.length})</span>
        </button>

        <button
          onClick={() => setActiveTab('serviceability')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeTab === 'serviceability'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Search className="w-4 h-4" />
          <span>Serviceability Check (Dry Run)</span>
        </button>

        <button
          onClick={() => setActiveTab('create_request')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeTab === 'create_request'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <PlusCircle className="w-4 h-4" />
          <span>New Collection Request</span>
        </button>
      </div>

      {feedback && (
        <div
          className={`p-4 rounded-xl text-sm flex items-center space-x-2 ${
            feedback.type === 'success'
              ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {feedback.type === 'success' ? (
            <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
          ) : (
            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0" />
          )}
          <span>{feedback.message}</span>
        </div>
      )}

      {/* 1. My Samples & Requests Tab */}
      {activeTab === 'samples' && (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div>
              <h2 className="text-xl font-bold text-slate-900">Your Clinical Sample Requests</h2>
              <p className="text-xs text-slate-500">
                Track status, current custody holder, location freshness, and route progress.
              </p>
            </div>
            <button
              onClick={() => setActiveTab('create_request')}
              className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold flex items-center space-x-2 shadow-sm transition"
            >
              <PlusCircle className="w-4 h-4" />
              <span>Request Pickup</span>
            </button>
          </div>

          {samples.length === 0 ? (
            <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center space-y-3">
              <Package className="w-12 h-12 text-slate-300 mx-auto" />
              <h3 className="text-base font-bold text-slate-700">No Sample Requests Yet</h3>
              <p className="text-xs text-slate-500 max-w-sm mx-auto">
                Check serviceability for your location or submit your first clinical sample collection request.
              </p>
              <button
                onClick={() => setActiveTab('create_request')}
                className="mt-2 px-4 py-2 bg-teal-600 text-white rounded-lg text-xs font-semibold hover:bg-teal-700"
              >
                Create First Request
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {samples.map((s) => (
                <div
                  key={s.sample_id}
                  onClick={() => setSelectedSampleId(s.sample_id)}
                  data-testid="sample-card"
                  className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm hover:shadow-md hover:border-teal-500/50 cursor-pointer transition flex flex-col justify-between space-y-4"
                >
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="font-mono text-xs font-bold text-slate-800">
                        {s.sample_id.slice(0, 10)}...
                      </span>
                      <span
                        className={`text-xs px-2 py-0.5 rounded font-semibold capitalize ${
                          s.status === 'received_at_lab' || s.status === 'completed'
                            ? 'bg-emerald-100 text-emerald-800'
                            : s.status === 'in_transit'
                            ? 'bg-blue-100 text-blue-800'
                            : 'bg-amber-100 text-amber-800'
                        }`}
                      >
                        {s.status.replace(/_/g, ' ')}
                      </span>
                    </div>

                    {/* Exception Warning */}
                    {s.has_exception && (
                      <div
                        data-testid="sample-exception-indicator"
                        className="p-2 bg-red-50 border border-red-200 rounded text-xs text-red-700 font-bold flex items-center space-x-1.5"
                      >
                        <AlertTriangle className="w-3.5 h-3.5 text-red-600 flex-shrink-0" />
                        <span className="truncate">{s.exception_reason || 'Exception Flagged'}</span>
                      </div>
                    )}

                    <div className="text-xs text-slate-600 space-y-1">
                      <div className="flex justify-between">
                        <span className="text-slate-400">Sample Type:</span>
                        <span className="font-semibold text-slate-800">{s.sample_type_name || 'Standard'}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-slate-400">Current Holder:</span>
                        <span className="font-semibold text-slate-800" data-testid="card-custodian">
                          {s.current_holder_name || 'Pending Collector'}
                        </span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-slate-400">Location Freshness:</span>
                        <span
                          data-testid="card-freshness"
                          className={`text-[10px] font-bold px-1.5 py-0.2 rounded uppercase ${
                            s.is_location_stale
                              ? 'bg-amber-100 text-amber-800'
                              : 'bg-emerald-100 text-emerald-800'
                          }`}
                        >
                          {s.is_location_stale ? 'Stale' : 'Fresh'}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="border-t border-slate-100 pt-3 flex items-center justify-between text-xs text-teal-600 font-semibold">
                    <span>View Timeline & History</span>
                    <span>→</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 2. Serviceability Dry Run Tab */}
      {activeTab === 'serviceability' && (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-6">
          <div>
            <h2 className="text-xl font-bold text-slate-900">Serviceability Check (Dry Run)</h2>
            <p className="text-xs text-slate-500">
              Verify if a pickup origin, sample type, and time window can be serviced by active nodes and laboratories before booking.
              This dry run will not create a request or reserve capacity.
            </p>
          </div>

          <form onSubmit={handleCheckServiceability} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Latitude
              </label>
              <input
                type="number"
                step="any"
                required
                value={checkForm.originLatitude}
                onChange={(e) => setCheckForm({ ...checkForm, originLatitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Longitude
              </label>
              <input
                type="number"
                step="any"
                required
                value={checkForm.originLongitude}
                onChange={(e) => setCheckForm({ ...checkForm, originLongitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Sample Type
              </label>
              <select
                value={checkForm.sampleTypeId}
                onChange={(e) => setCheckForm({ ...checkForm, sampleTypeId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                {sampleTypes.map((st) => (
                  <option key={st.id} value={st.id}>
                    {st.name} ({st.code}) - {st.requires_cooling ? 'Cold Chain' : 'Ambient'}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Collection Window Earliest
              </label>
              <input
                type="datetime-local"
                required
                value={checkForm.collectionWindowEarliest}
                onChange={(e) => setCheckForm({ ...checkForm, collectionWindowEarliest: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Collection Window Latest
              </label>
              <input
                type="datetime-local"
                required
                value={checkForm.collectionWindowLatest}
                onChange={(e) => setCheckForm({ ...checkForm, collectionWindowLatest: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Delivery Deadline
              </label>
              <input
                type="datetime-local"
                required
                value={checkForm.deliveryDeadline}
                onChange={(e) => setCheckForm({ ...checkForm, deliveryDeadline: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="md:col-span-2 pt-2">
              <button
                type="submit"
                data-testid="check-serviceability-button"
                disabled={loading}
                className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold shadow-sm transition disabled:opacity-50"
              >
                {loading ? 'Evaluating Network...' : 'Check Serviceability'}
              </button>
            </div>
          </form>

          {/* Serviceability Result Card */}
          {serviceabilityResult && (
            <div
              data-testid="serviceability-result-card"
              className={`p-5 rounded-xl border ${
                serviceabilityResult.serviceable
                  ? 'bg-emerald-50 border-emerald-300'
                  : 'bg-red-50 border-red-300'
              }`}
            >
              <div className="flex items-center space-x-2">
                {serviceabilityResult.serviceable ? (
                  <CheckCircle2 className="w-6 h-6 text-emerald-600" />
                ) : (
                  <XCircle className="w-6 h-6 text-red-600" />
                )}
                <h3 className="text-base font-bold text-slate-900">
                  {serviceabilityResult.serviceable
                    ? 'Location & Sample are Serviceable'
                    : 'Location / Sample Not Serviceable'}
                </h3>
              </div>

              {serviceabilityResult.reasons && serviceabilityResult.reasons.length > 0 && (
                <ul className="mt-2 space-y-1 text-xs text-slate-700 list-disc list-inside">
                  {serviceabilityResult.reasons.map((r: string, idx: number) => (
                    <li key={idx}>{r}</li>
                  ))}
                </ul>
              )}

              {serviceabilityResult.serviceable && (
                <div className="mt-4 pt-3 border-t border-emerald-200 grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
                  <div>
                    <span className="text-slate-500 block">Nearest Node</span>
                    <span className="font-semibold text-slate-900">
                      {serviceabilityResult.nearestNodeName || 'Within 5 km radius'}
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-500 block">Distance</span>
                    <span className="font-semibold text-slate-900">
                      {serviceabilityResult.distanceKm ? `${serviceabilityResult.distanceKm.toFixed(2)} km` : '< 5.0 km'}
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-500 block">Accepting Lab</span>
                    <span className="font-semibold text-slate-900">
                      {serviceabilityResult.destinationLabName || 'Active Lab Available'}
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-500 block">Capacity Status</span>
                    <span className="font-semibold text-emerald-800">Available</span>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* 3. Create Request Tab */}
      {activeTab === 'create_request' && (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-6">
          <div>
            <h2 className="text-xl font-bold text-slate-900">Create Clinical Sample Collection Request</h2>
            <p className="text-xs text-slate-500">
              Submit a sample pickup request for a patient's home or a clinic.
            </p>
          </div>

          {requestFormError && (
            <div
              data-testid="request-form-error"
              className="p-4 rounded-xl bg-red-50 border border-red-300 text-red-800 text-xs font-semibold flex items-center space-x-2"
            >
              <AlertTriangle className="w-4 h-4 text-red-600 flex-shrink-0" />
              <span>{requestFormError}</span>
            </div>
          )}

          <form onSubmit={handleCreateRequest} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Type
              </label>
              <select
                value={requestForm.originType}
                onChange={(e) => setRequestForm({ ...requestForm, originType: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                <option value="home">Patient Home</option>
                <option value="clinic">Clinic</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Address
              </label>
              <input
                type="text"
                required
                value={requestForm.originAddress}
                onChange={(e) => setRequestForm({ ...requestForm, originAddress: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Latitude
              </label>
              <input
                type="number"
                step="any"
                required
                value={requestForm.originLatitude}
                onChange={(e) => setRequestForm({ ...requestForm, originLatitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Longitude
              </label>
              <input
                type="number"
                step="any"
                required
                value={requestForm.originLongitude}
                onChange={(e) => setRequestForm({ ...requestForm, originLongitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Sample Type
              </label>
              <select
                value={requestForm.sampleTypeId}
                onChange={(e) => setRequestForm({ ...requestForm, sampleTypeId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                {sampleTypes.map((st) => (
                  <option key={st.id} value={st.id}>
                    {st.name} ({st.code}) - {st.requires_cooling ? 'Cold Chain' : 'Ambient'}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Collection Window Earliest
              </label>
              <input
                type="datetime-local"
                required
                value={requestForm.collectionWindowEarliest}
                onChange={(e) => setRequestForm({ ...requestForm, collectionWindowEarliest: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Collection Window Latest
              </label>
              <input
                type="datetime-local"
                required
                value={requestForm.collectionWindowLatest}
                onChange={(e) => setRequestForm({ ...requestForm, collectionWindowLatest: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Delivery Deadline
              </label>
              <input
                type="datetime-local"
                required
                value={requestForm.deliveryDeadline}
                onChange={(e) => setRequestForm({ ...requestForm, deliveryDeadline: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Pickup Notes
              </label>
              <input
                type="text"
                value={requestForm.notes}
                onChange={(e) => setRequestForm({ ...requestForm, notes: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="md:col-span-2 pt-2">
              <button
                type="submit"
                data-testid="create-request-submit-button"
                disabled={loading}
                className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-semibold shadow-sm transition disabled:opacity-50"
              >
                {loading ? 'Submitting Request...' : 'Submit Collection Request'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Sample Detail Modal */}
      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          onClose={() => setSelectedSampleId(null)}
        />
      )}
    </div>
  );
};

