import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { api } from '../api/client';
import { CapacityPool } from '../types';
import {
  Layers,
  Thermometer,
  Box,
  TrendingUp,
  Edit2,
  CheckCircle2,
  AlertCircle,
  RefreshCw,
} from 'lucide-react';

export const CapacityView: React.FC = () => {
  const { user } = useAuth();
  const [capacities, setCapacities] = useState<CapacityPool[]>([]);
  const [loading, setLoading] = useState(false);
  const [editPool, setEditPool] = useState<CapacityPool | null>(null);
  const [editForm, setEditForm] = useState({ capacityUnits: 100, cooledCapacityUnits: 50 });
  const [saving, setSaving] = useState(false);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const fetchCapacities = async () => {
    try {
      setLoading(true);
      const ops = await api.readOperationsState();
      if (ops && ops.capacities) {
        setCapacities(ops.capacities);
      }
    } catch (err: any) {
      console.error('Failed to fetch capacities:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCapacities();
  }, []);

  const isLabWorker = user?.activeRole === 'laboratory_team';
  const isNodeWorker = user?.activeRole === 'node_handler';

  // If lab worker or node worker, prioritize or filter to their assigned facility
  const visibleCapacities = capacities.filter((c) => {
    if (isLabWorker && user.assignedLaboratoryId) {
      return c.resource_id === user.assignedLaboratoryId;
    }
    if (isNodeWorker && user.assignedNodeId) {
      return c.resource_id === user.assignedNodeId;
    }
    return true;
  });

  const handleOpenEdit = (pool: CapacityPool) => {
    setEditPool(pool);
    setEditForm({
      capacityUnits: pool.capacity_units,
      cooledCapacityUnits: pool.cooled_capacity_units,
    });
    setFeedback(null);
  };

  const handleSaveCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editPool) return;
    setSaving(true);
    setFeedback(null);
    try {
      await api.configureCapacity(
        editPool.resource_id,
        Number(editForm.capacityUnits),
        Number(editForm.cooledCapacityUnits)
      );
      setFeedback({ type: 'success', message: 'Capacity pool updated successfully!' });
      setEditPool(null);
      await fetchCapacities();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to update capacity' });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-slate-900" data-testid="capacity-view-title">
            Facility & Transport Capacity Pools
          </h2>
          <p className="text-xs text-slate-500">
            Monitor and configure regular and cooled storage/transport capacity units.
          </p>
        </div>
        <button
          onClick={fetchCapacities}
          disabled={loading}
          className="p-2 text-slate-500 hover:text-slate-700 rounded-lg hover:bg-slate-100 transition"
        >
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {feedback && (
        <div
          className={`p-4 rounded-xl text-sm flex items-center space-x-2 ${
            feedback.type === 'success'
              ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {feedback.type === 'success' ? (
            <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
          ) : (
            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
          )}
          <span>{feedback.message}</span>
        </div>
      )}

      {loading && visibleCapacities.length === 0 ? (
        <div className="py-12 text-center text-slate-500">Loading capacity data...</div>
      ) : visibleCapacities.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center text-slate-500 space-y-2">
          <Layers className="w-10 h-10 text-slate-300 mx-auto" />
          <p className="font-semibold text-slate-700">No capacity pools found</p>
          <p className="text-xs text-slate-400">
            {isLabWorker || isNodeWorker
              ? 'No facility assignment associated with your user account.'
              : 'No facilities configured yet.'}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {visibleCapacities.map((pool) => {
            const regUsed = pool.reserved_capacity_units || 0;
            const regTotal = pool.capacity_units || 1;
            const regPct = Math.min(100, Math.round((regUsed / regTotal) * 100));

            const coolUsed = pool.reserved_cooled_capacity_units || 0;
            const coolTotal = pool.cooled_capacity_units || 1;
            const coolPct = Math.min(100, Math.round((coolUsed / coolTotal) * 100));

            return (
              <div
                key={pool.resource_id}
                data-testid="capacity-pool-card"
                className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-5 flex flex-col justify-between"
              >
                <div className="space-y-4">
                  <div className="flex items-start justify-between">
                    <div>
                      <span className="text-[10px] font-bold px-2 py-0.5 rounded uppercase tracking-wider bg-slate-100 text-slate-700">
                        {pool.resource_type}
                      </span>
                      <h3 className="text-base font-bold text-slate-900 mt-1" data-testid="capacity-resource-name">
                        {pool.resource_name}
                      </h3>
                    </div>
                    <button
                      onClick={() => handleOpenEdit(pool)}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-teal-600 hover:bg-teal-50 transition"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Regular Capacity */}
                  <div className="bg-slate-50 p-3.5 rounded-xl border border-slate-200 space-y-2">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-slate-700 flex items-center">
                        <Box className="w-3.5 h-3.5 mr-1 text-slate-500" /> Regular Capacity
                      </span>
                      <span className="font-mono font-bold text-slate-900" data-testid="capacity-regular-units">
                        {pool.available_capacity_units} / {pool.capacity_units} units avail
                      </span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2 overflow-hidden">
                      <div
                        className={`h-2 rounded-full transition-all duration-300 ${
                          regPct > 90 ? 'bg-red-500' : regPct > 70 ? 'bg-amber-500' : 'bg-teal-500'
                        }`}
                        style={{ width: `${regPct}%` }}
                      />
                    </div>
                    <div className="flex justify-between text-[11px] text-slate-500">
                      <span>Reserved: {pool.reserved_capacity_units}</span>
                      <span>{regPct}% Utilized</span>
                    </div>
                  </div>

                  {/* Cooled Capacity */}
                  <div className="bg-sky-50/60 p-3.5 rounded-xl border border-sky-200/60 space-y-2">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-sky-900 flex items-center">
                        <Thermometer className="w-3.5 h-3.5 mr-1 text-sky-600" /> Cooled Storage (2-8°C)
                      </span>
                      <span className="font-mono font-bold text-sky-950" data-testid="capacity-cooled-units">
                        {pool.available_cooled_capacity_units} / {pool.cooled_capacity_units} units avail
                      </span>
                    </div>
                    <div className="w-full bg-sky-200 rounded-full h-2 overflow-hidden">
                      <div
                        className={`h-2 rounded-full transition-all duration-300 ${
                          coolPct > 90 ? 'bg-red-500' : coolPct > 70 ? 'bg-amber-500' : 'bg-sky-600'
                        }`}
                        style={{ width: `${coolPct}%` }}
                      />
                    </div>
                    <div className="flex justify-between text-[11px] text-sky-700">
                      <span>Reserved: {pool.reserved_cooled_capacity_units}</span>
                      <span>{coolPct}% Utilized</span>
                    </div>
                  </div>
                </div>

                <div className="pt-2 border-t border-slate-100 flex justify-end">
                  <button
                    onClick={() => handleOpenEdit(pool)}
                    className="text-xs font-semibold text-teal-600 hover:text-teal-700"
                  >
                    Adjust Capacity Limits →
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Edit Capacity Modal */}
      {editPool && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">
              Configure Capacity Limits: {editPool.resource_name}
            </h3>
            <form onSubmit={handleSaveCapacity} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Regular Capacity (units)
                </label>
                <input
                  type="number"
                  min="0"
                  required
                  value={editForm.capacityUnits}
                  onChange={(e) => setEditForm({ ...editForm, capacityUnits: parseInt(e.target.value) || 0 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Cooled Capacity (units)
                </label>
                <input
                  type="number"
                  min="0"
                  required
                  value={editForm.cooledCapacityUnits}
                  onChange={(e) => setEditForm({ ...editForm, cooledCapacityUnits: parseInt(e.target.value) || 0 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setEditPool(null)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-bold"
                >
                  {saving ? 'Saving...' : 'Save Capacity Limits'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

