                      onClick={() => handleOpenEdit(pool)}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-teal-600 hover:bg-teal-50 transition"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Regular Capacity */}
                  <div className="bg-slate-50 p-3.5 rounded-xl border border-slate-200 space-y-2">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-slate-700 flex items-center">
                        <Box className="w-3.5 h-3.5 mr-1 text-slate-500" /> Regular Capacity
                      </span>
                      <span className="font-mono font-bold text-slate-900" data-testid="capacity-regular-units">
                        {pool.available_capacity_units} / {pool.capacity_units} units avail
                      </span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2 overflow-hidden">
                      <div
                        className={`h-2 rounded-full transition-all duration-300 ${
                          regPct > 90 ? 'bg-red-500' : regPct > 70 ? 'bg-amber-500' : 'bg-teal-500'
                        }`}
                        style={{ width: `${regPct}%` }}
                      />
                    </div>
                    <div className="flex justify-between text-[11px] text-slate-500">
                      <span>Reserved: {pool.reserved_capacity_units}</span>
                      <span>{regPct}% Utilized</span>
                    </div>
                  </div>

                  {/* Cooled Capacity */}
                  <div className="bg-sky-50/60 p-3.5 rounded-xl border border-sky-200/60 space-y-2">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-sky-900 flex items-center">
                        <Thermometer className="w-3.5 h-3.5 mr-1 text-sky-600" /> Cooled Storage (2-8°C)
                      </span>
                      <span className="font-mono font-bold text-sky-950" data-testid="capacity-cooled-units">
                        {pool.available_cooled_capacity_units} / {pool.cooled_capacity_units} units avail
                      </span>
                    </div>
                    <div className="w-full bg-sky-200 rounded-full h-2 overflow-hidden">
                      <div
                        className={`h-2 rounded-full transition-all duration-300 ${
                          coolPct > 90 ? 'bg-red-500' : coolPct > 70 ? 'bg-amber-500' : 'bg-sky-600'
                        }`}
                        style={{ width: `${coolPct}%` }}
                      />
                    </div>
                    <div className="flex justify-between text-[11px] text-sky-700">
                      <span>Reserved: {pool.reserved_cooled_capacity_units}</span>
                      <span>{coolPct}% Utilized</span>
                    </div>
                  </div>
                </div>

                <div className="pt-2 border-t border-slate-100 flex justify-end">
                  <button
                    onClick={() => handleOpenEdit(pool)}
