                </label>
                <input
                  type="number"
                  min="0"
                  required
                  value={editForm.cooledCapacityUnits}
                  onChange={(e) => setEditForm({ ...editForm, cooledCapacityUnits: parseInt(e.target.value) || 0 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
