import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { OperationsState, SampleState, WorkAssignment } from '../types';
import { SampleDetailModal } from '../components/SampleDetailModal';
import {
  Activity,
  AlertTriangle,
  Layers,
  MapPin,
  Package,
  RefreshCw,
  Search,
  ShieldCheck,
  TrendingUp,
  UserCheck,
  Users,
  GitBranch,
  Split,
  Combine,
  Slash,
  AlertOctagon,
  CheckCircle2,
} from 'lucide-react';

export const DispatcherDashboard: React.FC = () => {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [loading, setLoading] = useState(false);
  const [activeCategory, setActiveCategory] = useState<'samples' | 'workers' | 'nodes' | 'replanning'>('samples');
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // Replanning & Journey actions
  const [disruptionModal, setDisruptionModal] = useState(false);
  const [disruptionForm, setDisruptionForm] = useState({
    resourceType: 'location',
    resourceId: '',
    reason: 'Temporary network outage',
    expectedDurationMinutes: 60,
  });

  const [rerouteModal, setRerouteModal] = useState(false);
  const [rerouteForm, setRerouteForm] = useState({
    journeyId: '',
    expectedPlanVersion: 1,
    rerouteReason: 'Node congestion or closure',
  });

  const [splitModal, setSplitModal] = useState(false);
  const [splitForm, setSplitForm] = useState({
    journeyId: '',
    expectedPlanVersion: 1,
    sampleIdsStr: '',
  });

  const [mergeModal, setMergeModal] = useState(false);
  const [mergeForm, setMergeForm] = useState({
    targetJourneyId: '',
    expectedPlanVersion: 1,
    sourceJourneyIdsStr: '',
  });

  const fetchOperations = async () => {
    try {
      setLoading(true);
      const data = await api.readOperationsState();
      setOps(data);
    } catch (err: any) {
      console.error('Failed to read operations state:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOperations();
    const interval = setInterval(fetchOperations, 10000); // 10s auto-refresh
    return () => clearInterval(interval);
  }, []);

  const handleReportDisruption = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      await api.reportDisruption(disruptionForm);
      setFeedback({ type: 'success', message: 'Disruption recorded and affected journeys replanned!' });
      setDisruptionModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to report disruption' });
    }
  };

  const handleReroute = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      await api.rerouteJourney({
        journeyId: rerouteForm.journeyId,
        expectedPlanVersion: Number(rerouteForm.expectedPlanVersion),
        rerouteReason: rerouteForm.rerouteReason,
      });
      setFeedback({ type: 'success', message: 'Journey replanned and rerouted successfully!' });
      setRerouteModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to reroute journey' });
    }
  };

  const handleSplit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      const sampleIds = splitForm.sampleIdsStr.split(',').map((s) => s.trim()).filter(Boolean);
      await api.splitJourney({
        journeyId: splitForm.journeyId,
        expectedPlanVersion: Number(splitForm.expectedPlanVersion),
        sampleIds,
      });
      setFeedback({ type: 'success', message: 'Journey split successfully into new plan!' });
      setSplitModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to split journey' });
    }
  };

  const handleMerge = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      const sources = mergeForm.sourceJourneyIdsStr.split(',').map((s) => s.trim()).filter(Boolean);
      await api.mergeJourneys({
        targetJourneyId: mergeForm.targetJourneyId,
        expectedPlanVersion: Number(mergeForm.expectedPlanVersion),
        sourceJourneyIds: sources,
      });
      setFeedback({ type: 'success', message: 'Journeys merged successfully!' });
      setMergeModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to merge journeys' });
    }
  };

  const metrics = ops?.metrics || {
    total_active_samples: 0,
    samples_in_transit: 0,
    exceptions_count: 0,
    stale_locations_count: 0,
    available_workers_count: 0,
    active_journeys_count: 0,
  };

  const samplesList = (ops?.samples || []).filter((s) => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      s.sample_id.toLowerCase().includes(q) ||
      (s.sample_type_name && s.sample_type_name.toLowerCase().includes(q)) ||
      (s.current_holder_name && s.current_holder_name.toLowerCase().includes(q)) ||
      s.status.toLowerCase().includes(q)
    );
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      {/* Header & Controls */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
