              className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-bold transition"
            >
              Configure Reroute
            </button>
          </div>

          {/* Split Card */}
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <div className="w-10 h-10 rounded-xl bg-purple-100 text-purple-700 flex items-center justify-center font-bold">
              <Split className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">Split Journey Batch</h3>
              <p className="text-xs text-slate-500 mt-1">
                Separate high-priority or incompatible samples into a new independent journey without losing custody history.
              </p>
            </div>
            <button
              onClick={() => setSplitModal(true)}
              className="w-full py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-xs font-bold transition"
            >
              Split Journey
            </button>
          </div>

          {/* Merge Card */}
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <div className="w-10 h-10 rounded-xl bg-emerald-100 text-emerald-700 flex items-center justify-center font-bold">
              <Combine className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">Merge Compatible Journeys</h3>
              <p className="text-xs text-slate-500 mt-1">
                Consolidate compatible samples into a shared multi-stop or batched journey to maximize transport capacity.
              </p>
            </div>
            <button
              onClick={() => setMergeModal(true)}
              className="w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold transition"
            >
              Merge Journeys
            </button>
          </div>
        </div>
      )}

      {/* Disruption Modal */}
      {disruptionModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Report Network Disruption</h3>
            <form onSubmit={handleReportDisruption} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Resource Type
                </label>
                <select
                  value={disruptionForm.resourceType}
                  onChange={(e) => setDisruptionForm({ ...disruptionForm, resourceType: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
                >
                  <option value="location">Location / Node / Lab</option>
                  <option value="connection">Connection / Route</option>
                  <option value="worker">Worker</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Resource ID
                </label>
                <input
                  type="text"
                  required
                  placeholder="Location or Connection UUID"
                  value={disruptionForm.resourceId}
                  onChange={(e) => setDisruptionForm({ ...disruptionForm, resourceId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Disruption Reason
                </label>
                <input
                  type="text"
                  required
                  value={disruptionForm.reason}
                  onChange={(e) => setDisruptionForm({ ...disruptionForm, reason: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setDisruptionModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-bold"
                >
                  Submit Disruption & Replan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Reroute Modal */}
      {rerouteModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Reroute Journey</h3>
            <form onSubmit={handleReroute} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={rerouteForm.journeyId}
                  onChange={(e) => setRerouteForm({ ...rerouteForm, journeyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={rerouteForm.expectedPlanVersion}
                  onChange={(e) => setRerouteForm({ ...rerouteForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Reroute Reason
                </label>
                <input
                  type="text"
                  required
                  value={rerouteForm.rerouteReason}
                  onChange={(e) => setRerouteForm({ ...rerouteForm, rerouteReason: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setRerouteModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold"
                >
                  Execute Reroute
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Split Modal */}
      {splitModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Split Journey Batch</h3>
            <form onSubmit={handleSplit} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Source Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={splitForm.journeyId}
                  onChange={(e) => setSplitForm({ ...splitForm, journeyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={splitForm.expectedPlanVersion}
                  onChange={(e) => setSplitForm({ ...splitForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Sample IDs to Split (comma-separated)
                </label>
                <input
                  type="text"
                  required
                  placeholder="uuid1, uuid2"
                  value={splitForm.sampleIdsStr}
                  onChange={(e) => setSplitForm({ ...splitForm, sampleIdsStr: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setSplitModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-sm font-bold"
                >
                  Split Batch
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Merge Modal */}
      {mergeModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Merge Journeys</h3>
            <form onSubmit={handleMerge} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Target Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={mergeForm.targetJourneyId}
                  onChange={(e) => setMergeForm({ ...mergeForm, targetJourneyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={mergeForm.expectedPlanVersion}
                  onChange={(e) => setMergeForm({ ...mergeForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Source Journey IDs (comma-separated)
                </label>
                <input
                  type="text"
                  required
                  placeholder="uuid1, uuid2"
                  value={mergeForm.sourceJourneyIdsStr}
                  onChange={(e) => setMergeForm({ ...mergeForm, sourceJourneyIdsStr: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setMergeModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-bold"
                >
                  Merge Journeys
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Sample Detail Modal */}
      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          onClose={() => setSelectedSampleId(null)}
        />
      )}
    </div>
  );
};
"}

