import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { OperationsState, SampleState, WorkAssignment } from '../types';
import { SampleDetailModal } from '../components/SampleDetailModal';
import {
  Activity,
  AlertTriangle,
  Layers,
  MapPin,
  Package,
  RefreshCw,
  Search,
  ShieldCheck,
  TrendingUp,
  UserCheck,
  Users,
  GitBranch,
  Split,
  Combine,
  Slash,
  AlertOctagon,
  CheckCircle2,
} from 'lucide-react';

export const DispatcherDashboard: React.FC = () => {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [loading, setLoading] = useState(false);
  const [activeCategory, setActiveCategory] = useState<'samples' | 'workers' | 'nodes' | 'replanning'>('samples');
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // Replanning & Journey actions
  const [disruptionModal, setDisruptionModal] = useState(false);
  const [disruptionForm, setDisruptionForm] = useState({
    resourceType: 'location',
    resourceId: '',
    reason: 'Temporary network outage',
    expectedDurationMinutes: 60,
  });

  const [rerouteModal, setRerouteModal] = useState(false);
  const [rerouteForm, setRerouteForm] = useState({
    journeyId: '',
    expectedPlanVersion: 1,
    rerouteReason: 'Node congestion or closure',
  });

  const [splitModal, setSplitModal] = useState(false);
  const [splitForm, setSplitForm] = useState({
    journeyId: '',
    expectedPlanVersion: 1,
    sampleIdsStr: '',
  });

  const [mergeModal, setMergeModal] = useState(false);
  const [mergeForm, setMergeForm] = useState({
    targetJourneyId: '',
    expectedPlanVersion: 1,
    sourceJourneyIdsStr: '',
  });

  const fetchOperations = async () => {
    try {
      setLoading(true);
      const data = await api.readOperationsState();
      setOps(data);
    } catch (err: any) {
      console.error('Failed to read operations state:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOperations();
    const interval = setInterval(fetchOperations, 10000); // 10s auto-refresh
    return () => clearInterval(interval);
  }, []);

  const handleReportDisruption = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      await api.reportDisruption(disruptionForm);
      setFeedback({ type: 'success', message: 'Disruption recorded and affected journeys replanned!' });
      setDisruptionModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to report disruption' });
    }
  };

  const handleReroute = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      await api.rerouteJourney({
        journeyId: rerouteForm.journeyId,
        expectedPlanVersion: Number(rerouteForm.expectedPlanVersion),
        rerouteReason: rerouteForm.rerouteReason,
      });
      setFeedback({ type: 'success', message: 'Journey replanned and rerouted successfully!' });
      setRerouteModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to reroute journey' });
    }
  };

  const handleSplit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      const sampleIds = splitForm.sampleIdsStr.split(',').map((s) => s.trim()).filter(Boolean);
      await api.splitJourney({
        journeyId: splitForm.journeyId,
        expectedPlanVersion: Number(splitForm.expectedPlanVersion),
        sampleIds,
      });
      setFeedback({ type: 'success', message: 'Journey split successfully into new plan!' });
      setSplitModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to split journey' });
    }
  };

  const handleMerge = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      const sources = mergeForm.sourceJourneyIdsStr.split(',').map((s) => s.trim()).filter(Boolean);
      await api.mergeJourneys({
        targetJourneyId: mergeForm.targetJourneyId,
        expectedPlanVersion: Number(mergeForm.expectedPlanVersion),
        sourceJourneyIds: sources,
      });
      setFeedback({ type: 'success', message: 'Journeys merged successfully!' });
      setMergeModal(false);
      await fetchOperations();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to merge journeys' });
    }
  };

  const metrics = ops?.metrics || {
    total_active_samples: 0,
    samples_in_transit: 0,
    exceptions_count: 0,
    stale_locations_count: 0,
    available_workers_count: 0,
    active_journeys_count: 0,
  };

  const samplesList = (ops?.samples || []).filter((s) => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      s.sample_id.toLowerCase().includes(q) ||
      (s.sample_type_name && s.sample_type_name.toLowerCase().includes(q)) ||
      (s.current_holder_name && s.current_holder_name.toLowerCase().includes(q)) ||
      s.status.toLowerCase().includes(q)
    );
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      {/* Header & Controls */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-900" data-testid="monitor-dashboard-title">
            Operations & Dispatch Control Monitor
          </h2>
          <p className="text-xs text-slate-500">
            Real-time tracking of active samples, custody chain, capacity utilization, and network replanning.
          </p>
        </div>

        <div className="flex items-center space-x-2">
          <button
            onClick={() => setDisruptionModal(true)}
            className="px-3.5 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-bold shadow-sm transition flex items-center space-x-1.5"
          >
            <AlertOctagon className="w-3.5 h-3.5" />
            <span>Report Disruption</span>
          </button>

          <button
            onClick={fetchOperations}
            disabled={loading}
            className="p-2 text-slate-500 hover:text-slate-700 rounded-lg hover:bg-slate-100 transition border border-slate-200"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          </button>
        </div>
      </div>

      {feedback && (
        <div
          className={`p-4 rounded-xl text-sm flex items-center space-x-2 ${
            feedback.type === 'success'
              ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {feedback.type === 'success' ? (
            <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
          ) : (
            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0" />
          )}
          <span>{feedback.message}</span>
        </div>
      )}

      {/* Summary Metrics Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3.5" data-testid="dashboard-metrics">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-1">
          <div className="text-[11px] font-semibold text-slate-500 uppercase">Active Samples</div>
          <div className="text-2xl font-black text-slate-900" data-testid="metric-active-samples">
            {metrics.total_active_samples}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-1">
          <div className="text-[11px] font-semibold text-slate-500 uppercase">In Transit</div>
          <div className="text-2xl font-black text-blue-600" data-testid="metric-in-transit">
            {metrics.samples_in_transit}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-1">
          <div className="text-[11px] font-semibold text-slate-500 uppercase">Exceptions Flagged</div>
          <div
            className={`text-2xl font-black ${metrics.exceptions_count > 0 ? 'text-red-600' : 'text-slate-900'}`}
            data-testid="metric-exceptions"
          >
            {metrics.exceptions_count}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-1">
          <div className="text-[11px] font-semibold text-slate-500 uppercase">Stale Locations</div>
          <div
            className={`text-2xl font-black ${metrics.stale_locations_count > 0 ? 'text-amber-600' : 'text-slate-900'}`}
            data-testid="metric-stale-locations"
          >
            {metrics.stale_locations_count}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-1">
          <div className="text-[11px] font-semibold text-slate-500 uppercase">Workers on Duty</div>
          <div className="text-2xl font-black text-teal-600" data-testid="metric-workers-available">
            {metrics.available_workers_count}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-1">
          <div className="text-[11px] font-semibold text-slate-500 uppercase">Active Journeys</div>
          <div className="text-2xl font-black text-purple-600" data-testid="metric-active-journeys">
            {metrics.active_journeys_count}
          </div>
        </div>
      </div>

      {/* Category Tabs */}
      <div className="flex border-b border-slate-200 space-x-1" data-testid="monitor-categories">
        <button
          onClick={() => setActiveCategory('samples')}
          data-testid="category-tab-samples"
          className={`py-3 px-5 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeCategory === 'samples'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Package className="w-4 h-4" />
          <span>Samples & Custody ({samplesList.length})</span>
        </button>

        <button
          onClick={() => setActiveCategory('workers')}
          data-testid="category-tab-workers"
          className={`py-3 px-5 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeCategory === 'workers'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Users className="w-4 h-4" />
          <span>Staff & Couriers ({(ops?.workers || []).length})</span>
        </button>

        <button
          onClick={() => setActiveCategory('nodes')}
          data-testid="category-tab-nodes"
          className={`py-3 px-5 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeCategory === 'nodes'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Layers className="w-4 h-4" />
          <span>Nodes & Capacities ({(ops?.locations || []).length})</span>
        </button>

        <button
          onClick={() => setActiveCategory('replanning')}
          data-testid="category-tab-replanning"
          className={`py-3 px-5 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            activeCategory === 'replanning'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <GitBranch className="w-4 h-4" />
          <span>Journey Replanning Controls</span>
        </button>
      </div>

      {/* 1. Samples Table Category */}
      {activeCategory === 'samples' && (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div className="relative w-full max-w-sm">
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search sample ID, holder, status..."
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>
          </div>

          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
            <table className="min-w-full divide-y divide-slate-200 text-left text-xs">
              <thead className="bg-slate-50 text-slate-500 uppercase font-semibold">
                <tr>
                  <th className="px-4 py-3">Sample ID</th>
                  <th className="px-4 py-3">Type</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Current Holder</th>
                  <th className="px-4 py-3">Location & Freshness</th>
                  <th className="px-4 py-3">Exceptions</th>
                  <th className="px-4 py-3">Deadline</th>
                  <th className="px-4 py-3 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 font-medium text-slate-700">
                {samplesList.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="px-4 py-8 text-center text-slate-400">
                      No samples matching filters.
                    </td>
                  </tr>
                ) : (
                  samplesList.map((s) => (
                    <tr key={s.sample_id} className="hover:bg-slate-50/80 transition">
                      <td className="px-4 py-3 font-mono font-bold text-slate-900">
                        {s.sample_id.slice(0, 10)}...
                      </td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-0.5 rounded bg-slate-100 text-slate-800 text-[11px]">
                          {s.sample_type_name || 'Standard'}
                        </span>
                      </td>
                      <td className="px-4 py-3 capitalize">
                        <span
                          className={`px-2 py-0.5 rounded text-[11px] font-bold ${
                            s.status === 'received_at_lab' || s.status === 'completed'
                              ? 'bg-emerald-100 text-emerald-800'
                              : s.status === 'in_transit'
                              ? 'bg-blue-100 text-blue-800'
                              : 'bg-amber-100 text-amber-800'
                          }`}
                        >
                          {s.status.replace(/_/g, ' ')}
                        </span>
                      </td>
                      <td className="px-4 py-3 font-semibold text-slate-900">
                        {s.current_holder_name || 'Pending Pickup'}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center space-x-1.5">
                          <span className="truncate max-w-[120px]">
                            {s.current_location_name || (s.latest_latitude ? `${s.latest_latitude.toFixed(2)}, ${s.latest_longitude?.toFixed(2)}` : 'Origin')}
                          </span>
                          <span
                            className={`text-[9px] font-bold px-1.5 py-0.2 rounded uppercase ${
                              s.is_location_stale
                                ? 'bg-amber-100 text-amber-800'
                                : 'bg-emerald-100 text-emerald-800'
                            }`}
                          >
                            {s.is_location_stale ? 'Stale' : 'Fresh'}
                          </span>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        {s.has_exception ? (
                          <span className="text-red-600 font-bold flex items-center space-x-1 text-[11px]">
                            <AlertTriangle className="w-3.5 h-3.5 flex-shrink-0" />
                            <span className="truncate max-w-[100px]">{s.exception_reason || 'Exception'}</span>
                          </span>
                        ) : (
                          <span className="text-slate-400">None</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-slate-500">
                        {s.delivery_deadline ? new Date(s.delivery_deadline).toLocaleTimeString() : 'N/A'}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={() => setSelectedSampleId(s.sample_id)}
                          className="text-teal-600 hover:text-teal-700 font-bold text-xs"
                        >
                          View Lifecycle →
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 2. Workers Category */}
      {activeCategory === 'workers' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {(ops?.workers || []).map((w) => (
            <div key={w.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-bold text-slate-900 text-sm">{w.name}</h4>
                  <p className="text-xs text-slate-500 capitalize">{w.roles.join(', ').replace(/_/g, ' ')}</p>
                </div>
                <span
                  className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${
                    w.is_available ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-600'
                  }`}
                >
                  {w.is_available ? 'Available' : 'Unavailable'}
                </span>
              </div>

              <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs space-y-1.5 text-slate-600">
                <div className="flex justify-between">
                  <span>Assigned Node:</span>
                  <span className="font-semibold text-slate-800">{w.assigned_node_name || 'None'}</span>
                </div>
                <div className="flex justify-between">
                  <span>Assigned Lab:</span>
                  <span className="font-semibold text-slate-800">{w.assigned_lab_name || 'None'}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span>Location Freshness:</span>
                  <span
                    className={`text-[9px] font-bold px-1.5 py-0.2 rounded uppercase ${
                      w.is_location_stale ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'
                    }`}
                  >
                    {w.is_location_stale ? 'Stale' : 'Fresh'}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>Active Assignments:</span>
                  <span className="font-bold text-teal-700">{w.active_assignment_count}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 3. Nodes & Capacities Category */}
      {activeCategory === 'nodes' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {(ops?.locations || []).map((loc) => (
            <div key={loc.id} className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-bold text-slate-900 text-sm">{loc.name}</h4>
                  <p className="text-xs text-slate-500 capitalize">{loc.type} ({loc.functions.join(', ')})</p>
                </div>
                <span
                  className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${
                    loc.is_active ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                  }`}
                >
                  {loc.is_active ? 'Active' : 'Inactive'}
                </span>
              </div>

              <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs space-y-1.5 text-slate-600">
                <div className="flex justify-between">
                  <span>Regular Capacity:</span>
                  <span className="font-semibold text-slate-800">
                    {loc.capacity_units - (loc.reserved_capacity_units || 0)} / {loc.capacity_units} available
                  </span>
                </div>
                <div className="flex justify-between">
                  <span>Cooled Capacity:</span>
                  <span className="font-semibold text-slate-800">
                    {loc.cooled_capacity_units - (loc.reserved_cooled_capacity_units || 0)} / {loc.cooled_capacity_units} available
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 4. Journey Replanning Controls */}
      {activeCategory === 'replanning' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Reroute Card */}
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <div className="w-10 h-10 rounded-xl bg-blue-100 text-blue-700 flex items-center justify-center font-bold">
              <GitBranch className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">Reroute Active Journey</h3>
              <p className="text-xs text-slate-500 mt-1">
                Recompute routing and transfer legs for unfinished work while strictly preserving completed custody steps.
              </p>
            </div>
            <button
              onClick={() => setRerouteModal(true)}
              className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-bold transition"
            >
              Configure Reroute
            </button>
          </div>

          {/* Split Card */}
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <div className="w-10 h-10 rounded-xl bg-purple-100 text-purple-700 flex items-center justify-center font-bold">
              <Split className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">Split Journey Batch</h3>
              <p className="text-xs text-slate-500 mt-1">
                Separate high-priority or incompatible samples into a new independent journey without losing custody history.
              </p>
            </div>
            <button
              onClick={() => setSplitModal(true)}
              className="w-full py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-xs font-bold transition"
            >
              Split Journey
            </button>
          </div>

          {/* Merge Card */}
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <div className="w-10 h-10 rounded-xl bg-emerald-100 text-emerald-700 flex items-center justify-center font-bold">
              <Combine className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">Merge Compatible Journeys</h3>
              <p className="text-xs text-slate-500 mt-1">
                Consolidate compatible samples into a shared multi-stop or batched journey to maximize transport capacity.
              </p>
            </div>
            <button
              onClick={() => setMergeModal(true)}
              className="w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold transition"
            >
              Merge Journeys
            </button>
          </div>
        </div>
      )}

      {/* Disruption Modal */}
      {disruptionModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Report Network Disruption</h3>
            <form onSubmit={handleReportDisruption} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Resource Type
                </label>
                <select
                  value={disruptionForm.resourceType}
                  onChange={(e) => setDisruptionForm({ ...disruptionForm, resourceType: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
                >
                  <option value="location">Location / Node / Lab</option>
                  <option value="connection">Connection / Route</option>
                  <option value="worker">Worker</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Resource ID
                </label>
                <input
                  type="text"
                  required
                  placeholder="Location or Connection UUID"
                  value={disruptionForm.resourceId}
                  onChange={(e) => setDisruptionForm({ ...disruptionForm, resourceId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Disruption Reason
                </label>
                <input
                  type="text"
                  required
                  value={disruptionForm.reason}
                  onChange={(e) => setDisruptionForm({ ...disruptionForm, reason: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setDisruptionModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-bold"
                >
                  Submit Disruption & Replan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Reroute Modal */}
      {rerouteModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Reroute Journey</h3>
            <form onSubmit={handleReroute} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={rerouteForm.journeyId}
                  onChange={(e) => setRerouteForm({ ...rerouteForm, journeyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={rerouteForm.expectedPlanVersion}
                  onChange={(e) => setRerouteForm({ ...rerouteForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Reroute Reason
                </label>
                <input
                  type="text"
                  required
                  value={rerouteForm.rerouteReason}
                  onChange={(e) => setRerouteForm({ ...rerouteForm, rerouteReason: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setRerouteModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold"
                >
                  Execute Reroute
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Split Modal */}
      {splitModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Split Journey Batch</h3>
            <form onSubmit={handleSplit} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Source Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={splitForm.journeyId}
                  onChange={(e) => setSplitForm({ ...splitForm, journeyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={splitForm.expectedPlanVersion}
                  onChange={(e) => setSplitForm({ ...splitForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Sample IDs to Split (comma-separated)
                </label>
                <input
                  type="text"
                  required
                  placeholder="uuid1, uuid2"
                  value={splitForm.sampleIdsStr}
                  onChange={(e) => setSplitForm({ ...splitForm, sampleIdsStr: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setSplitModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-sm font-bold"
                >
                  Split Batch
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Merge Modal */}
      {mergeModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Merge Journeys</h3>
            <form onSubmit={handleMerge} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Target Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={mergeForm.targetJourneyId}
                  onChange={(e) => setMergeForm({ ...mergeForm, targetJourneyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={mergeForm.expectedPlanVersion}
                  onChange={(e) => setMergeForm({ ...mergeForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Source Journey IDs (comma-separated)
                </label>
                <input
                  type="text"
                  required
                  placeholder="uuid1, uuid2"
                  value={mergeForm.sourceJourneyIdsStr}
                  onChange={(e) => setMergeForm({ ...mergeForm, sourceJourneyIdsStr: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setMergeModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-bold"
                >
                  Merge Journeys
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Sample Detail Modal */}
      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          onClose={() => setSelectedSampleId(null)}
        />
      )}
    </div>
  );
};

