import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { AuditRecord } from '../types';
import { Search, ShieldAlert, Clock, User, FileText, CheckCircle2, XCircle } from 'lucide-react';

export const AuditView: React.FC = () => {
  const [records, setRecords] = useState<AuditRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({
    entityType: '',
    entityId: '',
    actorUserId: '',
    actorRole: '',
    action: '',
  });

  const searchAudit = async () => {
    try {
      setLoading(true);
      const res = await api.searchAuditTrail({
        entityType: filters.entityType || undefined,
        entityId: filters.entityId || undefined,
        actorUserId: filters.actorUserId || undefined,
        actorRole: filters.actorRole || undefined,
        action: filters.action || undefined,
        limit: 100,
      });
      setRecords(res || []);
    } catch (err: any) {
      console.error('Audit search error:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    searchAudit();
  }, []);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    searchAudit();
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6" data-testid="audit-view">
      <div>
        <h2 className="text-xl font-bold text-slate-900" data-testid="audit-view-title">
          Audit Trail & Security Logs
        </h2>
        <p className="text-xs text-slate-500">
          Search tamper-evident audit records covering sign-ins, custody handoffs, overrides, and exceptions.
        </p>
      </div>

      {/* Search Filters Card */}
      <form onSubmit={handleSearchSubmit} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-5 gap-3">
          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Entity Type
            </label>
            <select
              value={filters.entityType}
              onChange={(e) => setFilters({ ...filters, entityType: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs bg-white"
            >
              <option value="">All Entities</option>
              <option value="sample">Sample</option>
              <option value="journey">Journey</option>
              <option value="assignment">Assignment</option>
              <option value="location">Location</option>
              <option value="user">User</option>
            </select>
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Entity ID
            </label>
            <input
              type="text"
              placeholder="UUID"
              value={filters.entityId}
              onChange={(e) => setFilters({ ...filters, entityId: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs"
            />
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Actor Role
            </label>
            <select
              value={filters.actorRole}
              onChange={(e) => setFilters({ ...filters, actorRole: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs bg-white"
            >
              <option value="">All Roles</option>
              <option value="requester">Requester</option>
              <option value="collection_professional">Collection Pro</option>
              <option value="delivery_partner">Relay Courier</option>
              <option value="node_handler">Node Handler</option>
              <option value="laboratory_team">Lab Team</option>
              <option value="dispatcher">Dispatcher</option>
              <option value="administrator">Administrator</option>
            </select>
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Action Name
            </label>
            <input
              type="text"
              placeholder="e.g. handoff, create"
              value={filters.action}
              onChange={(e) => setFilters({ ...filters, action: e.target.value })}
