import React, { useEffect, useRef, useState } from 'react';
import * as maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';
import { NetworkLocation } from '../types';

interface MapViewProps {
  locations?: NetworkLocation[];
  workers?: {
    id: string;
    name: string;
    last_latitude?: number;
    last_longitude?: number;
    roles?: string[];
    is_location_stale?: boolean;
  }[];
  samples?: {
    sample_id: string;
    sample_type_name?: string;
    latest_latitude?: number;
    latest_longitude?: number;
    status: string;
    is_location_stale: boolean;
    has_exception: boolean;
  }[];
  selectedCoords?: [number, number]; // [lng, lat]
  onMapClick?: (lng: number, lat: number) => void;
  height?: string;
}

let protocolAdded = false;

export const MapView: React.FC<MapViewProps> = ({
  locations = [],
  workers = [],
  samples = [],
  selectedCoords,
  onMapClick,
  height = '550px',
}) => {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);
  const [mapLoaded, setMapLoaded] = useState(false);

  useEffect(() => {
    if (!protocolAdded) {
      const protocol = new pmtiles.Protocol();
      maplibregl.addProtocol('pmtiles', protocol.tile);
      protocolAdded = true;
    }

    if (!mapContainer.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: '/map-assets/style.json',
      center: [77.5946, 12.9716], // Bangalore center
      zoom: 11,
      minZoom: 9,
      maxZoom: 15,
    });

    map.addControl(new maplibregl.NavigationControl(), 'top-right');

    map.on('load', () => {
      setMapLoaded(true);
    });

    map.on('click', (e) => {
      if (onMapClick) {
        onMapClick(e.lngLat.lng, e.lngLat.lat);
      }
    });

    mapRef.current = map;

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  // Update markers whenever props change
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    // Clear old markers
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    // Render Location Markers
    locations.forEach((loc) => {
      if (!loc.latitude || !loc.longitude) return;
      const el = document.createElement('div');
      el.className = 'location-marker';
      const isLab = loc.functions?.includes('laboratory') || loc.type === 'laboratory';
      const isHub = loc.functions?.includes('hub') || loc.type === 'hub';

      el.style.width = '24px';
      el.style.height = '24px';
      el.style.borderRadius = '50%';
      el.style.border = '2px solid white';
      el.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
      el.style.backgroundColor = isLab ? '#dc2626' : isHub ? '#2563eb' : '#059669';
      el.style.cursor = 'pointer';

      const popup = new maplibregl.Popup({ offset: 15 }).setHTML(`
        <div class="p-2 text-xs font-sans">
          <strong class="font-bold text-sm block">${loc.name}</strong>
          <span class="text-slate-600 block">${loc.type} (${loc.functions?.join(', ') || 'node'})</span>
          <span class="block mt-1">Reg Cap: ${loc.capacity_units - (loc.reserved_capacity_units || 0)}/${loc.capacity_units}</span>
          <span class="block">Cool Cap: ${loc.cooled_capacity_units - (loc.reserved_cooled_capacity_units || 0)}/${loc.cooled_capacity_units}</span>
          <span class="inline-block mt-1 px-1.5 py-0.5 rounded text-[10px] ${loc.is_active ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}">
            ${loc.is_active ? 'Active' : 'Inactive'}
          </span>
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([loc.longitude, loc.latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Render Worker / Courier Markers
    workers.forEach((w) => {
      if (!w.last_latitude || !w.last_longitude) return;
      const el = document.createElement('div');
      el.className = 'worker-marker';
      el.style.width = '20px';
      el.style.height = '20px';
      el.style.borderRadius = '4px';
      el.style.border = '2px solid white';
      el.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
      el.style.backgroundColor = w.is_location_stale ? '#f59e0b' : '#7c3aed';
      el.style.cursor = 'pointer';

      const popup = new maplibregl.Popup({ offset: 15 }).setHTML(`
        <div class="p-2 text-xs font-sans">
          <strong class="font-bold text-sm block">${w.name}</strong>
          <span class="text-slate-600 block">${w.roles?.join(', ') || 'worker'}</span>
          <span class="inline-block mt-1 px-1.5 py-0.5 rounded text-[10px] ${w.is_location_stale ? 'bg-amber-100 text-amber-800' : 'bg-green-100 text-green-800'}">
            ${w.is_location_stale ? 'Location Stale' : 'Location Fresh'}
          </span>
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([w.last_longitude, w.last_latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Render Sample Markers
    samples.forEach((s) => {
      if (!s.latest_latitude || !s.latest_longitude) return;
      const el = document.createElement('div');
      el.className = 'sample-marker';
      el.style.width = '16px';
      el.style.height = '16px';
      el.style.borderRadius = '50%';
      el.style.border = '2px solid white';
      el.style.backgroundColor = s.has_exception ? '#ef4444' : '#06b6d4';
      el.style.cursor = 'pointer';

      const popup = new maplibregl.Popup({ offset: 10 }).setHTML(`
        <div class="p-2 text-xs font-sans">
          <strong class="font-bold text-xs block">Sample: ${s.sample_id.slice(0, 8)}...</strong>
          <span class="text-slate-600 block">Type: ${s.sample_type_name || 'Standard'}</span>
          <span class="text-slate-600 block">Status: ${s.status}</span>
          ${s.has_exception ? '<span class="text-red-600 font-bold block mt-1">⚠ EXCEPTION FLAGGED</span>' : ''}
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([s.latest_longitude, s.latest_latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Selected click marker
    if (selectedCoords && selectedCoords[0] && selectedCoords[1]) {
      const el = document.createElement('div');
      el.style.width = '14px';
      el.style.height = '14px';
      el.style.borderRadius = '50%';
      el.style.backgroundColor = '#ec4899';
      el.style.border = '2px solid white';

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([selectedCoords[0], selectedCoords[1]])
        .addTo(map);
      markersRef.current.push(marker);
    }
  }, [locations, workers, samples, selectedCoords, mapLoaded]);

  return (
    <div className="relative rounded-xl overflow-hidden border border-slate-200 shadow-sm bg-slate-100">
      <div
        ref={mapContainer}
        data-testid="maplibre-container"
        style={{ width: '100%', height }}
      />
      {/* Map Legend */}
      <div className="absolute bottom-4 left-4 bg-white/95 backdrop-blur-sm p-2.5 rounded-lg shadow-md border border-slate-200 text-xs flex flex-col space-y-1.5 z-10">
        <div className="font-semibold text-slate-800 text-[11px] uppercase tracking-wider mb-0.5">
          Map Legend
        </div>
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-red-600 border border-white"></div>
          <span className="text-slate-700">Laboratory</span>
        </div>
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-blue-600 border border-white"></div>
          <span className="text-slate-700">Hub / Transfer</span>
        </div>
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-emerald-600 border border-white"></div>
          <span className="text-slate-700">Collection Point</span>
        </div>
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded bg-purple-600 border border-white"></div>
          <span className="text-slate-700">Worker / Courier</span>
        </div>
        <div className="flex items-center space-x-2">
          <div className="w-3 h-3 rounded-full bg-cyan-500 border border-white"></div>
          <span className="text-slate-700">Active Sample</span>
        </div>
      </div>
    </div>
  );
};

